#[cfg(test)]
tokio::task_local! {
    /// Causal receipt currently owning diagnostic work in this task.
    ///
    /// Spawn boundaries explicitly propagate this value. At `schedule()`, it
    /// is transferred to a superseded predecessor so a cancel-vs-consume
    /// backstop cannot outlive the originating handler receipt.
    static DIAGNOSTIC_FINAL_HANDOFF_CONTEXT: crate::state::FinalHandoffCausalContext;
}

const DIAGNOSTIC_FANOUT_CONCURRENCY: usize = 8;
/// Maximum concurrent close-resync bursts per backend service.
///
/// Cloned backend handles share this cap, while independent services do not
/// contend for the same permits.
const CLOSE_RESYNC_CONCURRENCY: usize = 4;

use crate::r_subprocess::is_valid_package_name;

#[cfg(test)]
async fn run_in_diagnostic_final_handoff_context<F>(
    context: Option<crate::state::FinalHandoffCausalContext>,
    future: F,
) where
    F: Future<Output = ()>,
{
    if let Some(context) = context {
        DIAGNOSTIC_FINAL_HANDOFF_CONTEXT
            .scope(context, future)
            .await;
    } else {
        future.await;
    }
}

#[cfg(test)]
async fn run_with_diagnostic_final_handoff_completion<T, F>(
    completion: Option<crate::state::FinalHandoffCompletionToken<T>>,
    future: F,
) where
    T: Send + Sync + 'static,
    F: Future<Output = ()>,
{
    if let Some(completion) = completion {
        let context = completion.causal_context();
        DIAGNOSTIC_FINAL_HANDOFF_CONTEXT
            .scope(context, future)
            .await;
        completion.finish();
    } else {
        future.await;
    }
}

#[cfg(test)]
struct DiagnosticsSupersessionGuardForTest {
    registry: crate::state::DiagnosticsSupersessionHandoffMapForTest,
    uri: Url,
    generation: u64,
}

#[cfg(test)]
impl DiagnosticsSupersessionGuardForTest {
    fn take_handoff(
        &mut self,
    ) -> Option<(
        crate::state::FinalHandoffCausalContext,
        crate::state::FinalHandoffCausalToken,
    )> {
        self.registry
            .lock()
            .unwrap()
            .remove(&(self.uri.clone(), self.generation))
    }
}

#[cfg(test)]
impl Drop for DiagnosticsSupersessionGuardForTest {
    fn drop(&mut self) {
        if let Some((_, completion)) = self
            .registry
            .lock()
            .unwrap()
            .remove(&(self.uri.clone(), self.generation))
        {
            completion.finish();
        }
    }
}

/// Extract a permissive package warm set from durable metadata.
///
/// Conditional lexical calls and targets pipeline packages are intentionally
/// included. Warming cannot make a package semantically visible, and resolving
/// the full graph here would make the edit-time path disproportionately
/// expensive.
fn extract_loaded_packages_from_metadata(
    metadata: &crate::cross_file::CrossFileMetadata,
) -> Vec<String> {
    let mut packages = Vec::new();
    for package in metadata.referenced_packages() {
        if is_valid_package_name(package) {
            packages.push(package.to_string());
        } else {
            log::warn!("Skipping suspicious package name: {package}");
        }
    }
    packages
}

/// Direct package warm set for a single edited document: its validated
/// `library()`/`require()` loads plus the packages named in its
/// `data(..., package = "pkg")` calls (issue #429). Warming the latter lets the
/// diagnostics-time `data()` alias expansion resolve those packages' dataset
/// objects on live edits — parity with did_open and `raven check`, which both
/// warm `doc.data_packages`. `data_packages` names are validated downstream by
/// the `is_valid_package_name` filter the caller applies to the merged
/// prefetch set (mirroring the did_open path). Extracted for unit testing.
fn edited_document_warm_packages(
    metadata: &crate::cross_file::CrossFileMetadata,
    doc: &crate::state::Document,
) -> Vec<String> {
    let mut packages = extract_loaded_packages_from_metadata(metadata);
    packages.extend(doc.data_packages.iter().cloned());
    packages
}

/// Namespace-reference package names that pass the warm filter: a valid package
/// name that is not the load-all sentinel.
///
/// Single source of truth for "which `pkg::` packages may be warmed", shared by
/// every warm path (`namespace_warm_packages`, `collect_open_document_packages`)
/// because `prefetch_packages()` trusts its callers. Namespace references warm
/// metadata only — they never attach the package to bare-name scope.
fn valid_namespace_ref_packages(
    meta: &crate::cross_file::CrossFileMetadata,
) -> impl Iterator<Item = &str> {
    meta.namespace_references
        .iter()
        .map(|r| r.package.as_str())
        .filter(|p| is_valid_package_name(p) && !crate::package_library::is_load_all_sentinel(p))
}

/// Deduplicated package names worth warming from a document's namespace
/// references, in first-seen order.
fn namespace_warm_packages(meta: &crate::cross_file::CrossFileMetadata) -> Vec<String> {
    let mut seen = std::collections::HashSet::new();
    let mut packages = Vec::new();
    for p in valid_namespace_ref_packages(meta) {
        if seen.insert(p) {
            packages.push(p.to_string());
        }
    }
    packages
}

