        schedule_sysdata_fallback(handles, owner).await;
        backend.routing_tasks.wait().await;
        assert!(
            !state.read().await.sysdata_fallback_retry.has_pending(),
            "post-drain admission cannot mint retry currency or an untracked root"
        );
