    #[derive(Debug, Clone, Copy)]
    enum WorkspaceScanAuthorityDrift {
        PackageInput,
        PackageConfig,
        SystemRouting,
    }

    #[tokio::test]
    async fn workspace_scan_package_and_routing_drift_rejections_are_strict_noops() {
        for drift in [
            WorkspaceScanAuthorityDrift::PackageInput,
            WorkspaceScanAuthorityDrift::PackageConfig,
            WorkspaceScanAuthorityDrift::SystemRouting,
        ] {
            let tmp = TempDir::new().unwrap();
            let uri = Url::from_file_path(tmp.path().join("open.R")).unwrap();
            let uris = vec![uri.clone()];
            let state = Arc::new(RwLock::new(WorldState::new()));
            let inputs = {
                let mut state = state.write().await;
                state.workspace_folders = vec![Url::from_file_path(tmp.path()).unwrap()];
                state.open_document(uri.clone(), "value <- 1\n", Some(1));
                let intent = state.begin_workspace_scan_intent();
                WorkspaceScanInputs::capture(&state, intent).unwrap()
            };
            let prepared = prepare_workspace_scan(&state, &inputs, HashMap::new())
                .await
                .unwrap();
            let expected = {
                let mut state = state.write().await;
                match drift {
                    WorkspaceScanAuthorityDrift::PackageInput => {
                        state.record_package_input_mutation();
                    }
                    WorkspaceScanAuthorityDrift::PackageConfig => {
                        state.bump_package_config_generation();
                    }
                    WorkspaceScanAuthorityDrift::SystemRouting => {
                        let mut library = crate::package_library::PackageLibrary::new_empty();
                        library.set_lib_paths(vec![tmp.path().join("library")]);
                        state.package_library = Arc::new(library);
                    }
                }
                workspace_scan_central_snapshot(&state, &uris)
            };
            let mut state = state.write().await;
            assert_eq!(
                state
                    .try_commit_analysis(PreparedAnalysisCommit::WorkspaceScan(Box::new(prepared))),
                Err(crate::state::AnalysisCommitRejected::StaleBasis),
                "{drift:?} drift must reject the old candidate"
            );
            assert_eq!(
                workspace_scan_central_snapshot(&state, &uris),
                expected,
                "{drift:?} rejection must not mutate another central tier"
            );
        }
    }

    #[tokio::test]
    async fn workspace_scan_transfer_does_not_attach_to_reopened_lifecycle() {
        let tmp = TempDir::new().unwrap();
        let uri = Url::from_file_path(tmp.path().join("reopened.R")).unwrap();
        let state = Arc::new(RwLock::new(WorldState::new()));
        let inputs = {
            let mut state = state.write().await;
            state.workspace_folders = vec![Url::from_file_path(tmp.path()).unwrap()];
            state.open_document(uri.clone(), "value <- 1\n", Some(1));
            state
                .begin_open_document_diagnostic_lifecycle(&uri)
                .unwrap();
            let intent = state.begin_workspace_scan_intent();
            WorkspaceScanInputs::capture(&state, intent).unwrap()
        };
        let prepared = prepare_workspace_scan(&state, &inputs, HashMap::new())
            .await
            .unwrap();
        let mut state = state.write().await;
        let effects = state
            .try_commit_analysis(PreparedAnalysisCommit::WorkspaceScan(Box::new(prepared)))
            .unwrap();
        let transfer = effects.workspace_scan.unwrap();
        let committed_generation = state.documents.get_record(&uri).unwrap().generation();
        assert_eq!(state.analysis_revalidation_reservation_count, 0);
        assert_eq!(
            state.diagnostics_gate.force_republish_count_for_test(&uri),
            0
        );

        state.retire_diagnostic_lifecycle(&uri);
        state.close_document(&uri);
        state.open_document(uri.clone(), "value <- 1\n", Some(1));
        let reopened_epoch = state
            .begin_open_document_diagnostic_lifecycle(&uri)
            .unwrap();
        let reopened = state.documents.get_record(&uri).unwrap();
        assert_ne!(reopened.generation(), committed_generation);
        assert_eq!(reopened.provenance().lifecycle_epoch, Some(reopened_epoch));

        assert!(
            state.claim_workspace_scan_transfer(&transfer).is_empty(),
            "a transferred token from the retired record must not attach to the reopen"
        );
        assert_eq!(state.analysis_revalidation_reservation_count, 0);
        assert_eq!(
            state.diagnostics_gate.force_republish_count_for_test(&uri),
            0
        );
        assert_eq!(
            state
                .documents
                .get_record(&uri)
                .unwrap()
                .provenance()
                .lifecycle_epoch,
            Some(reopened_epoch)
        );
    }

    #[tokio::test]
    async fn workspace_scan_transfer_survives_unrelated_watcher_and_filters_changed_open() {
        let tmp = TempDir::new().unwrap();
        let changed_uri = Url::from_file_path(tmp.path().join("changed-open.R")).unwrap();
        let retained_uri = Url::from_file_path(tmp.path().join("retained-open.R")).unwrap();
        let watched_path = tmp.path().join("unrelated-closed.R");
        let watched_uri = Url::from_file_path(&watched_path).unwrap();
        fs::write(&watched_path, "watched <- 1\n").unwrap();
        let state = Arc::new(RwLock::new(WorldState::new()));
        let inputs = {
            let mut state = state.write().await;
            state.workspace_folders = vec![Url::from_file_path(tmp.path()).unwrap()];
            for uri in [&changed_uri, &retained_uri] {
                state.open_document(uri.clone(), "value <- 1\n", Some(1));
                state.begin_open_document_diagnostic_lifecycle(uri).unwrap();
            }
            let intent = state.begin_workspace_scan_intent();
            WorkspaceScanInputs::capture(&state, intent).unwrap()
        };
        let prepared = prepare_workspace_scan(&state, &inputs, HashMap::new())
            .await
            .unwrap();
        let transfer = state
            .write()
            .await
            .try_commit_analysis(PreparedAnalysisCommit::WorkspaceScan(Box::new(prepared)))
            .unwrap()
            .workspace_scan
            .unwrap();

        let watched_generation = {
            let mut state = state.write().await;
            let generation = bump_watched_file_resync_generation(&mut state, &watched_uri);
            let open_generation = state
                .documents
                .get_record(&changed_uri)
                .unwrap()
                .generation();
            let mut metadata = crate::cross_file::CrossFileMetadata::default();
            metadata.working_directory = Some("/changed-after-scan".to_string());
            state
                .replace_open_document_metadata_if_current(
                    &changed_uri,
                    open_generation,
                    Arc::new(metadata),
                )
                .unwrap();
            generation
        };
        assert!(matches!(
            resync_file_from_disk(
                &state,
                &watched_uri,
                None,
                None,
                false,
                Some(watched_generation),
                ResyncCommitMode::Immediate,
            )
            .await,
            ResyncOutcome::Updated { .. }
        ));

        let mut state = state.write().await;
        let reservation_before = state.analysis_revalidation_reservation_count;
        let retained_force_before = state
            .diagnostics_gate
            .force_republish_count_for_test(&retained_uri);
        let tickets = state.claim_workspace_scan_transfer(&transfer);
        assert_eq!(
            tickets
                .iter()
                .map(|ticket| ticket.uri.clone())
                .collect::<Vec<_>>(),
            vec![retained_uri.clone()]
        );
        assert_eq!(
            state.analysis_revalidation_reservation_count,
            reservation_before + 1
        );
        assert_eq!(
            state
                .diagnostics_gate
                .force_republish_count_for_test(&retained_uri),
            retained_force_before + 1
        );
        assert!(
            tickets.iter().all(|ticket| ticket.uri != changed_uri),
            "the later open owner must filter the stale transferred token"
        );
    }

    #[tokio::test]
    async fn workspace_scan_exclusion_reload_transfer_is_sole_marker_owner() {
        let tmp = TempDir::new().unwrap();
        fs::create_dir(tmp.path().join("generated")).unwrap();
        fs::write(tmp.path().join("generated/helper.R"), "helper_value <- 1\n").unwrap();
        let open_uri = Url::from_file_path(tmp.path().join("main.R")).unwrap();
        let state_root = Url::from_file_path(tmp.path()).unwrap();
        let (service, _socket) = tower_lsp::LspService::new(Backend::new);
        let backend = service.inner();
        {
            let mut state = backend.state.write().await;
            state.workspace_folders = vec![state_root];
            state.raw_client_settings = serde_json::json!({
                "packages": { "enabled": false }
            });
            state.raw_project_settings =
                Some(serde_json::json!({ "workspace": { "exclude": [] } }));
            crate::config_file::recompute_parsed_configs(&mut state);
            state.open_document(
                open_uri.clone(),
                "source(\"generated/helper.R\")\nhelper_value\n",
                Some(1),
            );
        }
        let initial = run_workspace_scan_transaction(&backend.state)
            .await
            .expect_committed();
        {
            let mut state = backend.state.write().await;
            assert!(
                state
                    .claim_workspace_scan_transfer(&initial.transfer)
                    .is_empty(),
                "the initial epochless open has no marker owner"
            );
            state
                .begin_open_document_diagnostic_lifecycle(&open_uri)
                .unwrap();
            assert_eq!(
                state
                    .diagnostics_gate
                    .force_republish_count_for_test(&open_uri),
                0
            );
        }

        let (previous, reservations_before) = {
            let mut state = backend.state.write().await;
            let previous = ConfigChangeSnapshot::capture(&state);
            state.raw_project_settings =
                Some(serde_json::json!({ "workspace": { "exclude": ["generated/**"] } }));
            crate::config_file::recompute_parsed_configs(&mut state);
            (previous, state.analysis_revalidation_reservation_count)
        };
        assert!(
            backend
                .reconcile_after_config_recompute(previous)
                .await
                .is_empty(),
            "the committed scan transfer publishes its own exact tickets"
        );

        let state = backend.state.read().await;
        assert_eq!(
            state.analysis_revalidation_reservation_count,
            reservations_before + 1,
            "the overlapping exclusion and scan effects must reserve once"
        );
        assert_eq!(
            state
                .diagnostics_gate
                .force_republish_count_for_test(&open_uri),
            0,
            "the one transfer worker must consume the sole force marker"
        );
    }

    #[tokio::test]
    async fn workspace_scan_preserves_retained_external_graph_roots() {
        let tmp = TempDir::new().unwrap();
        let root = tmp.path().join("workspace");
        let external = tmp.path().join("external");
        fs::create_dir_all(&root).unwrap();
        fs::create_dir_all(external.join("data")).unwrap();
        fs::write(root.join("main.R"), "workspace_value <- 1\n").unwrap();
        let external_path = external.join("helper.R");
        let leaf_path = external.join("data/leaf.R");
        let filler_path = external.join("filler.R");
        fs::write(
            &external_path,
            "source(\"data/leaf.R\")\nexternal_value <- 1\n",
        )
        .unwrap();
        fs::write(&leaf_path, "leaf_value <- 1\n").unwrap();
        fs::write(&filler_path, "filler_value <- 1\n").unwrap();
        let external_uri = Url::from_file_path(&external_path).unwrap();
        let leaf_uri = Url::from_file_path(&leaf_path).unwrap();
        let filler_uri = Url::from_file_path(&filler_path).unwrap();

        let (svc, _socket) = tower_lsp::LspService::new(Backend::new);
        let backend = svc.inner();
        backend
            .initialize(InitializeParams {
                workspace_folders: Some(vec![WorkspaceFolder {
                    uri: Url::from_file_path(&root).unwrap(),
                    name: "workspace".into(),
                }]),
                ..Default::default()
            })
            .await
            .unwrap();
        {
            let mut state = backend.state.write().await;
            state.workspace_index = crate::workspace_index::WorkspaceIndex::new(
                crate::workspace_index::WorkspaceIndexConfig {
                    max_files: 1,
                    ..Default::default()
                },
            );
        }
        backend
            .index_file_on_demand(&external_uri)
            .await
            .expect("external helper should index");
        backend
            .index_file_on_demand(&filler_uri)
            .await
            .expect("filler should displace only the helper full payload");
        {
            let state = backend.state.read().await;
            let snapshot = state.workspace_index.authority_snapshot();
            assert!(
                state.workspace_index.get(&external_uri).is_none(),
                "expected artifact-only helper; full={:?}, artifacts={:?}, cap={}",
                snapshot
                    .full
                    .iter()
                    .map(|(uri, _)| uri.as_str())
                    .collect::<Vec<_>>(),
                snapshot
                    .artifacts
                    .iter()
                    .map(|(uri, _)| uri.as_str())
                    .collect::<Vec<_>>(),
                state.workspace_index.cap(),
            );
            assert!(state.workspace_index.is_complete(&external_uri));
        }
        run_workspace_scan_transaction(&backend.state)
            .await
            .expect_committed();

        let state = backend.state.read().await;
        assert!(state.workspace_index.get(&external_uri).is_none());
        assert!(state.workspace_index.is_complete(&external_uri));
        assert!(
            state
                .cross_file_graph
                .get_dependencies(&external_uri)
                .iter()
                .any(|edge| edge.to == leaf_uri),
            "retained non-scan roots must remain represented by the replacement graph"
        );
    }

    #[tokio::test]
    async fn workspace_scan_graph_matches_artifact_residency() {
        let tmp = TempDir::new().unwrap();
        let root = tmp.path().join("workspace");
        fs::create_dir_all(&root).unwrap();
        for name in ["a", "b", "c"] {
            fs::write(
                root.join(format!("{name}.R")),
                format!("source(\"{name}.txt\")\n"),
            )
            .unwrap();
            fs::write(root.join(format!("{name}.txt")), "").unwrap();
        }

        let (svc, _socket) = tower_lsp::LspService::new(Backend::new);
        let backend = svc.inner();
        backend
            .initialize(InitializeParams {
                workspace_folders: Some(vec![WorkspaceFolder {
                    uri: Url::from_file_path(&root).unwrap(),
                    name: "workspace".into(),
                }]),
                initialization_options: Some(serde_json::json!({
                    "crossFile": { "indexWorkspace": false },
                    "packages": { "enabled": false }
                })),
                ..Default::default()
            })
            .await
            .unwrap();
        {
            let mut state = backend.state.write().await;
            state.workspace_index = crate::workspace_index::WorkspaceIndex::new(
                crate::workspace_index::WorkspaceIndexConfig {
                    max_files: 1,
                    ..Default::default()
                },
            );
            state.workspace_index.resize_artifacts(1);
            state.cross_file_config.index_workspace = true;
            state.advance_workspace_scan_generation();
        }
        run_workspace_scan_transaction(&backend.state)
            .await
            .expect_committed();

        let state = backend.state.read().await;
        let full_resident: std::collections::HashSet<_> =
            state.workspace_index.uris().into_iter().collect();
        let artifact_resident: std::collections::HashSet<_> =
            state.workspace_index.artifact_uris().into_iter().collect();
        assert_eq!(full_resident.len(), 1);
        assert_eq!(artifact_resident.len(), 1);
        for name in ["a", "b", "c"] {
            let uri = Url::from_file_path(root.join(format!("{name}.R"))).unwrap();
            assert_eq!(
                !state.cross_file_graph.get_dependencies(&uri).is_empty(),
                artifact_resident.contains(&uri),
                "graph roots must exactly match post-cap artifact residency"
            );
        }
    }

