    #[tokio::test]
    async fn sequential_system_file_transfers_retain_unclaimed_candidates() {
        let workspace = TempDir::new().unwrap();
        let library = TempDir::new().unwrap();
        let package = library.path().join("otherpkg");
        fs::create_dir_all(&package).unwrap();
        fs::write(package.join("helper.R"), "helper_value <- 1\n").unwrap();
        let uri = Url::from_file_path(workspace.path().join("main.R")).unwrap();
        let state = Arc::new(RwLock::new(WorldState::new()));
        {
            let mut state = state.write().await;
            state.workspace_folders = vec![Url::from_file_path(workspace.path()).unwrap()];
            state.open_document(
                uri.clone(),
                "source(system.file(\"helper.R\", package = \"otherpkg\"))\n",
                Some(1),
            );
            state
                .begin_open_document_diagnostic_lifecycle(&uri)
                .unwrap();
            let mut package_library = crate::package_library::PackageLibrary::new_empty();
            package_library.set_lib_paths(vec![library.path().to_path_buf()]);
            state.install_package_library(Arc::new(package_library), true);
        }
        let first = match run_system_file_convergence_transaction(&state, None).await {
            SystemFileConvergenceOutcome::Committed(effects) => effects.handle,
            SystemFileConvergenceOutcome::Superseded(_) => {
                panic!("first convergence was superseded")
            }
            SystemFileConvergenceOutcome::Deferred => {
                panic!("first convergence exhausted retries")
            }
        };
        let second = match run_system_file_convergence_transaction(&state, None).await {
            SystemFileConvergenceOutcome::Committed(effects) => effects.handle,
            SystemFileConvergenceOutcome::Superseded(_) => {
                panic!("second convergence was superseded")
            }
            SystemFileConvergenceOutcome::Deferred => {
                panic!("second convergence exhausted retries")
            }
        };
        let mut state = state.write().await;
        assert_eq!(
            state.finalize_analysis_transfers(
                WorldState::begin_analysis_transfer_finalization(),
                &[first],
                Vec::new(),
            ),
            Err(AnalysisTransferRejection::Superseded {
                previous: first,
                successor: second,
            })
        );
        let tickets = state
            .finalize_analysis_transfers(
                WorldState::begin_analysis_transfer_finalization(),
                &[second],
                Vec::new(),
            )
            .unwrap();
        assert!(matches!(
            tickets,
            AnalysisTransferFinalization::Committed(ref tickets)
                if tickets.iter().any(|ticket| ticket.uri == uri)
        ));
    }

    #[tokio::test]
    async fn consumed_transfer_under_distinct_finalization_never_falls_back() {
        let workspace = TempDir::new().unwrap();
        let library = TempDir::new().unwrap();
        let package = library.path().join("otherpkg");
        fs::create_dir_all(&package).unwrap();
        fs::write(package.join("helper.R"), "helper_value <- 1\n").unwrap();
        let uri = Url::from_file_path(workspace.path().join("live.R")).unwrap();
        let independent = Url::from_file_path(workspace.path().join("independent.R")).unwrap();
        let source = "source(system.file(\"helper.R\", package = \"otherpkg\"))\n";
        let state = Arc::new(RwLock::new(WorldState::new()));
        {
            let mut state = state.write().await;
            state.workspace_folders = vec![Url::from_file_path(workspace.path()).unwrap()];
            state.open_document(uri.clone(), source, Some(1));
            state
                .begin_open_document_diagnostic_lifecycle(&uri)
                .unwrap();
            let generation = state.documents.get_record(&uri).unwrap().generation();
            state
                .replace_open_document_metadata_if_current(
                    &uri,
                    generation,
                    Arc::new(crate::cross_file::extract_metadata(source)),
                )
                .unwrap();
            state.open_document(independent.clone(), "independent <- 1\n", Some(1));
            state
                .begin_open_document_diagnostic_lifecycle(&independent)
                .unwrap();
            let mut package_library = crate::package_library::PackageLibrary::new_empty();
            package_library.set_lib_paths(vec![library.path().to_path_buf()]);
            state.install_package_library(Arc::new(package_library), true);
        }
        let handle = match run_system_file_convergence_transaction(&state, None).await {
            SystemFileConvergenceOutcome::Committed(transfer) => transfer.handle,
            SystemFileConvergenceOutcome::Superseded(_) => {
                panic!("fixture convergence was superseded")
            }
            SystemFileConvergenceOutcome::Deferred => panic!("fixture convergence was deferred"),
        };
        let mut state = state.write().await;
        let first = state
            .finalize_analysis_transfers(
                WorldState::begin_analysis_transfer_finalization(),
                &[handle],
                Vec::new(),
            )
            .unwrap();
        assert!(matches!(
            first,
            AnalysisTransferFinalization::Committed(ref tickets) if tickets.len() == 1
        ));
        let reservations = state.analysis_revalidation_reservation_count;
        let markers = state.diagnostics_gate.force_republish_count_for_test(&uri);

        let tickets = finalize_analysis_handoff_or_fallback(
            &mut state,
            vec![handle],
            vec![independent.clone()],
            vec![independent.clone()],
        );

        assert_eq!(
            tickets
                .iter()
                .map(|ticket| ticket.uri.clone())
                .collect::<Vec<_>>(),
            vec![independent.clone()],
            "the consumed handle owns its overlap, but independent direct candidates must still finalize"
        );
        assert_eq!(
            state.analysis_revalidation_reservation_count,
            reservations + 1
        );
        assert_eq!(
            state.diagnostics_gate.force_republish_count_for_test(&uri),
            markers,
            "AlreadyConsumed under another finalization is terminal, not fallback authority"
        );
    }

    #[tokio::test]
    async fn consumed_system_handle_does_not_strand_valid_workspace_transfer() {
        let workspace = TempDir::new().unwrap();
        let library = TempDir::new().unwrap();
        let package = library.path().join("otherpkg");
        fs::create_dir_all(&package).unwrap();
        fs::write(package.join("helper.R"), "helper_value <- 1\n").unwrap();
        let system_uri = Url::from_file_path(workspace.path().join("system.R")).unwrap();
        let workspace_uri = Url::from_file_path(workspace.path().join("workspace.R")).unwrap();
        let source = "source(system.file(\"helper.R\", package = \"otherpkg\"))\n";
        fs::write(system_uri.to_file_path().unwrap(), source).unwrap();
        fs::write(
            workspace_uri.to_file_path().unwrap(),
            "workspace_value <- 1\n",
        )
        .unwrap();
        let state = Arc::new(RwLock::new(WorldState::new()));
        {
            let mut state = state.write().await;
            state.workspace_folders = vec![Url::from_file_path(workspace.path()).unwrap()];
            state.open_document(system_uri.clone(), source, Some(1));
            state
                .begin_open_document_diagnostic_lifecycle(&system_uri)
                .unwrap();
            let generation = state
                .documents
                .get_record(&system_uri)
                .unwrap()
                .generation();
            state
                .replace_open_document_metadata_if_current(
                    &system_uri,
                    generation,
                    Arc::new(crate::cross_file::extract_metadata(source)),
                )
                .unwrap();
            state.open_document(workspace_uri.clone(), "workspace_value <- 1\n", Some(1));
            state
                .begin_open_document_diagnostic_lifecycle(&workspace_uri)
                .unwrap();
            let mut package_library = crate::package_library::PackageLibrary::new_empty();
            package_library.set_lib_paths(vec![library.path().to_path_buf()]);
            state.install_package_library(Arc::new(package_library), true);
        }
        let system_handle = run_system_file_convergence_transfer(&state, None)
            .await
            .unwrap()
            .handle;
        {
            let mut state = state.write().await;
            let finalized = state
                .finalize_analysis_transfers(
                    WorldState::begin_analysis_transfer_finalization(),
                    &[system_handle],
                    Vec::new(),
                )
                .unwrap();
            assert!(matches!(
                finalized,
                AnalysisTransferFinalization::Committed(ref tickets)
                    if tickets.iter().any(|ticket| ticket.uri == system_uri)
            ));
        }

        let workspace_handle = run_workspace_scan_transaction(&state)
            .await
            .expect_committed()
            .transfer
            .handle;
        let mut state = state.write().await;
        let system_markers = state
            .diagnostics_gate
            .force_republish_count_for_test(&system_uri);
        let tickets = finalize_analysis_handoff_or_fallback(
            &mut state,
            vec![system_handle, workspace_handle],
            Vec::new(),
            vec![workspace_uri.clone()],
        );
        assert!(
            tickets.iter().any(|ticket| ticket.uri == workspace_uri),
            "the consumed system handle is terminal only for itself"
        );
        assert!(
            tickets.iter().all(|ticket| ticket.uri != system_uri),
            "the valid workspace transfer must not reserve the overlap already owned by the consumed system handle"
        );
        assert_eq!(
            state
                .diagnostics_gate
                .force_republish_count_for_test(&system_uri),
            system_markers
        );
        assert_eq!(
            state
                .diagnostics_gate
                .force_republish_count_for_test(&workspace_uri),
            1
        );
    }

    #[tokio::test]
    async fn consumed_transfer_excludes_only_reserved_current_candidates() {
        let workspace = TempDir::new().unwrap();
        let library = TempDir::new().unwrap();
        let package = library.path().join("otherpkg");
        fs::create_dir_all(&package).unwrap();
        fs::write(package.join("helper.R"), "helper_value <- 1\n").unwrap();
        let dropped = Url::from_file_path(workspace.path().join("dropped.R")).unwrap();
        let reserved = Url::from_file_path(workspace.path().join("reserved.R")).unwrap();
        let source = "source(system.file(\"helper.R\", package = \"otherpkg\"))\n";
        let state = Arc::new(RwLock::new(WorldState::new()));
        {
            let mut state = state.write().await;
            state.workspace_folders = vec![Url::from_file_path(workspace.path()).unwrap()];
            state.cross_file_config.max_revalidations_per_trigger = 1;
            state.cross_file_activity.active_uri = Some(reserved.clone());
            for uri in [&dropped, &reserved] {
                state.open_document(uri.clone(), source, Some(1));
                state.begin_open_document_diagnostic_lifecycle(uri).unwrap();
                let generation = state.documents.get_record(uri).unwrap().generation();
                state
                    .replace_open_document_metadata_if_current(
                        uri,
                        generation,
                        Arc::new(crate::cross_file::extract_metadata(source)),
                    )
                    .unwrap();
            }
            let mut package_library = crate::package_library::PackageLibrary::new_empty();
            package_library.set_lib_paths(vec![library.path().to_path_buf()]);
            state.install_package_library(Arc::new(package_library), true);
        }
        let handle = run_system_file_convergence_transfer(&state, None)
            .await
            .unwrap()
            .handle;
        {
            let mut state = state.write().await;
            let first = state
                .finalize_analysis_transfers(
                    WorldState::begin_analysis_transfer_finalization(),
                    &[handle],
                    Vec::new(),
                )
                .unwrap();
            assert!(matches!(
                first,
                AnalysisTransferFinalization::Committed(ref tickets)
                    if tickets.len() == 1 && tickets[0].uri == reserved
            ));

            let dropped_tickets = finalize_analysis_handoff_or_fallback(
                &mut state,
                vec![handle],
                vec![dropped.clone()],
                vec![dropped.clone()],
            );
            assert_eq!(
                dropped_tickets
                    .iter()
                    .map(|ticket| ticket.uri.clone())
                    .collect::<Vec<_>>(),
                vec![dropped.clone()],
                "a cap-dropped candidate was not owned by the consumed finalization"
            );

            state.apply_package_event(&crate::package_state::PackageInputDelta::Initial);
            let later_semantic_tickets = finalize_analysis_handoff_or_fallback(
                &mut state,
                vec![handle],
                vec![reserved.clone()],
                vec![reserved.clone()],
            );
            assert_eq!(
                later_semantic_tickets
                    .iter()
                    .map(|ticket| ticket.uri.clone())
                    .collect::<Vec<_>>(),
                vec![reserved.clone()],
                "independent later semantic work on the same lifecycle is not transfer overlap"
            );

            state.retire_diagnostic_lifecycle(&reserved);
            state.close_document(&reserved);
            state.open_document(reserved.clone(), source, Some(1));
            state
                .begin_open_document_diagnostic_lifecycle(&reserved)
                .unwrap();
            let reopened_tickets = finalize_analysis_handoff_or_fallback(
                &mut state,
                vec![handle],
                vec![reserved.clone()],
                vec![reserved.clone()],
            );
            assert_eq!(
                reopened_tickets
                    .iter()
                    .map(|ticket| ticket.uri.clone())
                    .collect::<Vec<_>>(),
                vec![reserved.clone()],
                "a consumed candidate's retired token cannot suppress the reopened lifecycle"
            );
        }
    }

    #[tokio::test]
    async fn post_seed_candidate_close_reopen_before_finalization_is_dropped() {
        let workspace = TempDir::new().unwrap();
        let root = workspace.path().to_path_buf();
        let rprofile_uri = Url::from_file_path(root.join(".Rprofile")).unwrap();
        let uri = Url::from_file_path(root.join("live.R")).unwrap();
        let (svc, _socket) = tower_lsp::LspService::new(Backend::new);
        let backend = svc.inner();
        {
            let mut state = backend.state.write().await;
            state.workspace_folders = vec![Url::from_file_path(&root).unwrap()];
            establish_package_event_translation_state(&mut state, root.clone());
            state.open_document(rprofile_uri.clone(), "profile_value <- 1\n", Some(1));
            state
                .begin_open_document_diagnostic_lifecycle(&rprofile_uri)
                .unwrap();
            state.open_document(uri.clone(), "old <- profile_value\n", Some(1));
            state
                .begin_open_document_diagnostic_lifecycle(&uri)
                .unwrap();
        }
        let stale = Backend::refresh_open_package_inputs_after_seed_for_test(
            backend.state.clone(),
            backend.client.clone(),
            backend.traversal_truncation.clone(),
            root,
        )
        .await;
        assert!(
            stale.iter().any(|candidate| candidate.uri == uri),
            "the real post-seed refresh must capture the affected open consumer"
        );

        let mut state = backend.state.write().await;
        state.retire_diagnostic_lifecycle(&uri);
        state.close_document(&uri);
        state.open_document(uri.clone(), "new <- profile_value\n", Some(1));
        state
            .begin_open_document_diagnostic_lifecycle(&uri)
            .unwrap();

        let tickets = finalize_analysis_handoff_candidates_or_fallback(
            &mut state,
            Vec::new(),
            stale,
            vec![uri.clone()],
        );
        assert!(tickets.is_empty());
        assert_eq!(state.analysis_revalidation_reservation_count, 0);
        assert_eq!(
            state.diagnostics_gate.force_republish_count_for_test(&uri),
            0,
            "a refresh candidate is authority for only its captured open lifecycle"
        );
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn stale_seed_convergence_returns_current_successor_owner() {
        let state = Arc::new(RwLock::new(WorldState::new()));
        let old_seed = {
            let mut state = state.write().await;
            state.record_system_file_routing_owner_change();
            state.record_package_seed_installed()
        };
        let pause = state
            .read()
            .await
            .system_file_pre_derivation_test_pause
            .arm(Url::parse("raven-test://system-file-pre-derivation").unwrap());
        let task_state = state.clone();
        let task = tokio::spawn(async move {
            run_system_file_convergence_transaction_for_seed(&task_state, old_seed).await
        });
        pause.wait_arrived().await;
        let successor_owner = {
            let mut state = state.write().await;
            state.record_system_file_routing_owner_change();
            let newer_seed = state.record_package_seed_installed();
            assert_ne!(newer_seed, old_seed);
            newer_seed.system_file_routing_owner
        };
        pause.release();

        let SystemFileConvergenceOutcome::Superseded(successor) = task.await.unwrap() else {
            panic!("the stale seed must hand off to an explicit current-owner transfer");
        };
        assert_eq!(
            successor.handle.system_file_routing_owner_for_test(),
            Some(successor_owner)
        );
    }

