    #[derive(Clone, Copy)]
    enum SystemFileExternalDrift {
        InvalidToValid,
        ValidContentChange,
        ValidToMissing,
        ValidToInvalid,
        InvalidToMissing,
        MissingToInvalid,
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn system_file_external_identity_change_vetoes_stale_install() {
        for drift in [
            SystemFileExternalDrift::InvalidToValid,
            SystemFileExternalDrift::ValidContentChange,
            SystemFileExternalDrift::ValidToMissing,
            SystemFileExternalDrift::ValidToInvalid,
            SystemFileExternalDrift::InvalidToMissing,
            SystemFileExternalDrift::MissingToInvalid,
        ] {
            let workspace = TempDir::new().unwrap();
            let library = TempDir::new().unwrap();
            let package = library.path().join("otherpkg");
            fs::create_dir_all(&package).unwrap();
            let target = package.join("helper.R");
            match drift {
                SystemFileExternalDrift::InvalidToValid
                | SystemFileExternalDrift::InvalidToMissing => fs::write(&target, [0xff]).unwrap(),
                SystemFileExternalDrift::ValidContentChange
                | SystemFileExternalDrift::ValidToMissing
                | SystemFileExternalDrift::ValidToInvalid => {
                    fs::write(&target, "old <- 1\n").unwrap()
                }
                SystemFileExternalDrift::MissingToInvalid => {}
            }
            let uri = Url::from_file_path(workspace.path().join("main.R")).unwrap();
            let source = "source(system.file(\"helper.R\", package = \"otherpkg\"))\n";
            let state = Arc::new(RwLock::new(WorldState::new()));
            {
                let mut state = state.write().await;
                state.workspace_folders = vec![Url::from_file_path(workspace.path()).unwrap()];
                state.open_document(uri.clone(), source, Some(1));
                let generation = state.documents.get_record(&uri).unwrap().generation();
                state
                    .replace_open_document_metadata_if_current(
                        &uri,
                        generation,
                        Arc::new(crate::cross_file::extract_metadata(source)),
                    )
                    .unwrap();
                let mut package_library = crate::package_library::PackageLibrary::new_empty();
                package_library.set_lib_paths(vec![library.path().to_path_buf()]);
                state.install_package_library(Arc::new(package_library), true);
            }
            let pause = state
                .read()
                .await
                .system_file_pre_commit_test_pause
                .arm(Url::parse("raven-test://system-file-pre-commit").unwrap());
            let task_state = state.clone();
            let task = tokio::spawn(async move {
                run_system_file_convergence_transaction(&task_state, None).await
            });
            pause.wait_arrived().await;
            match drift {
                SystemFileExternalDrift::InvalidToValid
                | SystemFileExternalDrift::ValidContentChange => {
                    fs::write(&target, "new_value <- 12345\n").unwrap()
                }
                SystemFileExternalDrift::ValidToMissing
                | SystemFileExternalDrift::InvalidToMissing => fs::remove_file(&target).unwrap(),
                SystemFileExternalDrift::ValidToInvalid
                | SystemFileExternalDrift::MissingToInvalid => fs::write(&target, [0xff]).unwrap(),
            }
            pause.release();
            assert!(matches!(
                task.await.unwrap(),
                SystemFileConvergenceOutcome::Committed(_)
            ));
            let target_uri = Url::from_file_path(&target).unwrap();
            let state = state.read().await;
            match drift {
                SystemFileExternalDrift::InvalidToValid
                | SystemFileExternalDrift::ValidContentChange => {
                    assert_eq!(
                        state
                            .workspace_index
                            .get(&target_uri)
                            .unwrap()
                            .contents
                            .to_string(),
                        "new_value <- 12345\n"
                    );
                    assert_eq!(
                        state.documents.get_record(&uri).unwrap().metadata().sources[0]
                            .resolved_uri,
                        Some(target_uri)
                    );
                }
                SystemFileExternalDrift::ValidToMissing
                | SystemFileExternalDrift::InvalidToMissing => {
                    assert!(
                        !state.workspace_index.is_complete(&target_uri),
                        "a missing or invalid external target must not remain indexed"
                    );
                    assert_eq!(
                        state.documents.get_record(&uri).unwrap().metadata().sources[0]
                            .resolved_uri,
                        None
                    );
                }
                SystemFileExternalDrift::ValidToInvalid
                | SystemFileExternalDrift::MissingToInvalid => {
                    assert!(
                        !state.workspace_index.is_complete(&target_uri),
                        "an invalid external target must not remain indexed"
                    );
                    assert_eq!(
                        state.documents.get_record(&uri).unwrap().metadata().sources[0]
                            .resolved_uri,
                        Some(target_uri),
                        "path routing still resolves an existing file even when its contents are invalid"
                    );
                }
            }
        }
    }

    #[cfg(unix)]
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn alias_close_remirror_keeps_project_excluded_remaining_alias_non_lending() {
        let tmp = TempDir::new().unwrap();
        let real = tmp.path().join("real");
        let generated = tmp.path().join("generated");
        fs::create_dir(&real).unwrap();
        fs::create_dir(&generated).unwrap();
        std::os::unix::fs::symlink(&real, generated.join("a")).unwrap();
        std::os::unix::fs::symlink(&real, generated.join("b")).unwrap();
        fs::write(
            tmp.path().join("raven.toml"),
            "[workspace]\nexclude = [\"generated/**\"]\n",
        )
        .unwrap();
        fs::write(real.join("parent.R"), "source(\"child.R\")\n").unwrap();
        fs::write(real.join("child.R"), "child_value <- 1\n").unwrap();

        let root = Url::from_file_path(tmp.path()).unwrap();
        let alias_a = Url::from_file_path(generated.join("a").join("parent.R")).unwrap();
        let alias_b = Url::from_file_path(generated.join("b").join("parent.R")).unwrap();
        let canonical_parent = Url::from_file_path(real.join("parent.R")).unwrap();
        let child_uri = Url::from_file_path(real.join("child.R")).unwrap();
        let consumer_uri = Url::from_file_path(tmp.path().join("consumer.R")).unwrap();

        let (svc, _socket) = tower_lsp::LspService::new(Backend::new);
        let backend = svc.inner();
        backend
            .initialize(InitializeParams {
                workspace_folders: Some(vec![WorkspaceFolder {
                    uri: root,
                    name: "t".into(),
                }]),
                initialization_options: Some(serde_json::json!({
                    "packages": { "enabled": false }
                })),
                ..Default::default()
            })
            .await
            .unwrap();
        backend
            .state
            .write()
            .await
            .cross_file_config
            .revalidation_debounce_ms = 60_000;

        open_doc(
            backend,
            &alias_a,
            "r",
            1,
            "source(\"child.R\")\na_only <- 1\n",
        )
        .await;
        open_doc(
            backend,
            &alias_b,
            "r",
            1,
            "source(\"child.R\")\nb_only <- 1\n",
        )
        .await;
        open_doc(
            backend,
            &consumer_uri,
            "r",
            1,
            "source(\"real/parent.R\")\na_only\n",
        )
        .await;

        {
            let mut state = backend.state.write().await;
            state
                .watched_file_resync_generations
                .insert(canonical_parent.clone(), 4_242);
            assert!(state.is_project_excluded_uri(&alias_a));
            assert!(state.is_project_excluded_uri(&alias_b));
            assert!(!state.is_project_excluded_uri(&canonical_parent));
            assert_eq!(
                state.open_document_uri_for_authoritative_uri(&canonical_parent),
                Some(alias_a.clone()),
                "precondition: the first opened alias owns the canonical graph root"
            );
            assert!(
                has_dependency_edge(&state, &canonical_parent, &child_uri),
                "precondition: canonical root keeps the outgoing edge for live diagnostics"
            );
            assert!(
                state
                    .cross_file_graph
                    .get_dependents(&child_uri)
                    .iter()
                    .any(|edge| edge.from == canonical_parent && edge.non_lending),
                "precondition: excluded alias reverse edge must be retained but non-lending"
            );
            assert!(
                !state
                    .cross_file_graph
                    .get_dependents(&child_uri)
                    .iter()
                    .any(|edge| edge.from == canonical_parent && !edge.non_lending),
                "precondition: excluded alias must not have a lending reverse edge"
            );
        }

        let (transactional, resync, _) =
            close_with_final_handoff_capture(backend, &alias_a, false).await;

        let state = backend.state.read().await;
        assert_eq!(
            state.open_document_uri_for_authoritative_uri(&canonical_parent),
            Some(alias_b.clone()),
            "closing the first alias must promote the remaining alias"
        );
        assert!(
            has_dependency_edge(&state, &canonical_parent, &child_uri),
            "remirror should preserve the canonical root's outgoing edge"
        );
        assert!(
            state
                .cross_file_graph
                .get_dependents(&child_uri)
                .iter()
                .any(|edge| edge.from == canonical_parent && edge.non_lending),
            "remirror must retain the reverse edge for revalidation but mark it non-lending"
        );
        assert!(
            !state
                .cross_file_graph
                .get_dependents(&child_uri)
                .iter()
                .any(|edge| edge.from == canonical_parent && !edge.non_lending),
            "remirror must not recreate a lending reverse edge from the non-excluded child"
        );
        assert_eq!(
            state.watched_file_resync_generations.get(&canonical_parent),
            Some(&4_242),
            "surviving alias ownership must retain canonical watched authority"
        );
        assert_eq!(
            close_handoff_count(&transactional, &resync, &consumer_uri),
            1,
            "the canonical dependent must own one exact close-handoff consumer"
        );
        drop(state);
    }

    #[cfg(unix)]
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn alias_close_remirror_new_backward_edge_revalidates_new_dependent() {
        let tmp = TempDir::new().unwrap();
        let real = tmp.path().join("real");
        fs::create_dir(&real).unwrap();
        std::os::unix::fs::symlink(&real, tmp.path().join("a")).unwrap();
        std::os::unix::fs::symlink(&real, tmp.path().join("b")).unwrap();
        fs::write(real.join("parent.R"), "a_value <- 1\n").unwrap();
        fs::write(tmp.path().join("consumer.R"), "b_value\n").unwrap();

        let alias_a = Url::from_file_path(tmp.path().join("a/parent.R")).unwrap();
        let alias_b = Url::from_file_path(tmp.path().join("b/parent.R")).unwrap();
        let canonical_uri = Url::from_file_path(real.join("parent.R")).unwrap();
        let consumer_uri = Url::from_file_path(tmp.path().join("consumer.R")).unwrap();
        let (svc, _socket) = tower_lsp::LspService::new(Backend::new);
        let backend = svc.inner();
        backend
            .initialize(InitializeParams {
                workspace_folders: Some(vec![WorkspaceFolder {
                    uri: Url::from_file_path(tmp.path()).unwrap(),
                    name: "t".into(),
                }]),
                initialization_options: Some(serde_json::json!({
                    "crossFile": { "indexWorkspace": false },
                    "packages": { "enabled": false }
                })),
                ..Default::default()
            })
            .await
            .unwrap();
        backend
            .state
            .write()
            .await
            .cross_file_config
            .revalidation_debounce_ms = 60_000;

        open_doc(backend, &alias_a, "r", 1, "a_value <- 1\n").await;
        open_doc(
            backend,
            &alias_b,
            "r",
            1,
            "# raven: sourced-by ../consumer.R\nb_value <- 2\n",
        )
        .await;
        open_doc(backend, &consumer_uri, "r", 1, "b_value\n").await;

        {
            let state = backend.state.read().await;
            assert_eq!(
                state.open_document_uri_for_authoritative_uri(&canonical_uri),
                Some(alias_a.clone())
            );
            assert!(
                !has_dependency_edge(&state, &consumer_uri, &canonical_uri),
                "precondition: owner A does not expose alias B's backward edge"
            );
        }

        let (transactional, resync, _) =
            close_with_final_handoff_capture(backend, &alias_a, false).await;

        let state = backend.state.read().await;
        assert_eq!(
            state.open_document_uri_for_authoritative_uri(&canonical_uri),
            Some(alias_b)
        );
        assert!(
            has_dependency_edge(&state, &consumer_uri, &canonical_uri),
            "remirroring B must install its newly introduced backward edge"
        );
        assert_eq!(
            close_handoff_count(&transactional, &resync, &consumer_uri),
            1,
            "the newly introduced dependent must own one exact close-handoff consumer"
        );
        drop(state);
    }

