    /// A detached seed may finish after dirty package inputs have opened. The
    /// disk snapshot must be overlaid by authoritative DESCRIPTION, NAMESPACE,
    /// package-R, and `.Rprofile` buffers; the latter requires an explicit
    /// off-lock post-install refresh when its did_open scan has not committed yet.
    #[tokio::test]
    async fn seed_install_converges_all_open_package_inputs() {
        let tmp = TempDir::new().unwrap();
        let root = tmp.path().to_path_buf();
        fs::create_dir_all(root.join("R")).unwrap();
        fs::write(
            root.join("DESCRIPTION"),
            "Package: diskpkg\nVersion: 0.0.1\n",
        )
        .unwrap();
        fs::write(root.join("NAMESPACE"), "export(disk_fun)\n").unwrap();
        fs::write(root.join("R/fun.R"), "disk_fun <- function() 1\n").unwrap();
        fs::write(root.join(".Rprofile"), "disk_profile <- function() 1\n").unwrap();
        let exclusions = crate::config_file::CompiledWorkspaceExclusions::default();
        let stale_seed = PrecomputedPackageSeed::compute(
            &root,
            &exclusions,
            &crate::package_state::preamble::PreambleTextOverrides::new(),
            true,
        );

        let (svc, _socket) = tower_lsp::LspService::new(Backend::new);
        let backend = svc.inner();
        {
            let mut state = backend.state.write().await;
            establish_package_event_translation_state(&mut state, root.clone());
            for (relative, text) in [
                ("DESCRIPTION", "Package: bufferpkg\nVersion: 9.9.9\n"),
                ("NAMESPACE", "export(buffer_fun)\n"),
                ("R/fun.R", "buffer_fun <- function() 2\n"),
                (".Rprofile", "buffer_profile <- function() 3\n"),
            ] {
                let uri = Url::from_file_path(root.join(relative)).unwrap();
                state
                    .documents
                    .insert(uri.clone(), crate::state::Document::new(text, Some(7)));
                state.begin_diagnostic_lifecycle(&uri);
                if relative != ".Rprofile" {
                    let delta = crate::package_state::event::translate(
                        &mut state.package_inputs,
                        crate::package_state::event::HandlerEvent::DidOpen {
                            uri,
                            text: Arc::from(text),
                        },
                    )
                    .expect("pre-seed package event must translate once root state is established");
                    state.apply_package_event(&delta);
                }
            }
            assert_eq!(
                state
                    .package_inputs
                    .description
                    .as_ref()
                    .map(|input| &*input.text),
                Some("Package: bufferpkg\nVersion: 9.9.9\n")
            );
            assert!(state.package_inputs.rprofile_symbols.is_empty());
            stale_seed.install(&mut state);

            assert_eq!(
                state
                    .package_inputs
                    .description
                    .as_ref()
                    .map(|input| &*input.text),
                Some("Package: bufferpkg\nVersion: 9.9.9\n")
            );
            assert_eq!(
                state
                    .package_inputs
                    .namespace
                    .as_ref()
                    .map(|input| &*input.text),
                Some("export(buffer_fun)\n")
            );
            assert_eq!(
                state
                    .package_inputs
                    .r_files
                    .get(&root.join("R/fun.R"))
                    .map(|input| &*input.text),
                Some("buffer_fun <- function() 2\n")
            );
            assert!(
                state.package_inputs.rprofile_symbols.is_empty(),
                "an open .Rprofile makes seed installation defer to the live refresh"
            );
        }

        Backend::refresh_open_package_inputs_after_seed_for_test(
            backend.state.clone(),
            backend.client.clone(),
            backend.traversal_truncation.clone(),
            root,
        )
        .await;

        let state = backend.state.read().await;
        assert!(
            state
                .package_inputs
                .rprofile_symbols
                .contains("buffer_profile")
        );
        assert!(
            !state
                .package_inputs
                .rprofile_symbols
                .contains("disk_profile")
        );
    }

    fn establish_combined_post_seed_fixture(
        state: &mut WorldState,
        root: &std::path::Path,
        rprofile_uri: &Url,
        preamble_uri: &Url,
    ) -> PackageSeedInstalledIdentity {
        establish_package_event_translation_state(state, root.to_path_buf());
        let exclusions = crate::config_file::CompiledWorkspaceExclusions::default();
        initialize_package_inputs_from_state_with_exclusions(
            state,
            root.to_path_buf(),
            Some(Arc::from(
                "Package: combinedtail\nVersion: 0.0.1\nSuggests: testthat\n",
            )),
            None,
            Default::default(),
            Some(
                crate::package_state::rprofile::scan_workspace_rprofile_with_exclusions(
                    root,
                    &exclusions,
                ),
            ),
            Some(
                crate::package_state::preamble::scan_testthat_preambles_with_exclusions(
                    root,
                    &exclusions,
                ),
            ),
            &exclusions,
        );
        state.documents.insert(
            rprofile_uri.clone(),
            crate::state::Document::new(
                "source(\"scripts/shared.R\")\nprofile_live <- 1\n",
                Some(1),
            ),
        );
        state.begin_diagnostic_lifecycle(rprofile_uri);
        state.documents.insert(
            preamble_uri.clone(),
            crate::state::Document::new(
                "source(\"../../scripts/shared.R\")\npreamble_live <- 1\n",
                Some(1),
            ),
        );
        state.begin_diagnostic_lifecycle(preamble_uri);
        let shared_uri = Url::from_file_path(root.join("scripts/shared.R")).unwrap();
        state.documents.insert(
            shared_uri.clone(),
            crate::state::Document::new("live_shared <- 1\n", Some(1)),
        );
        state.begin_diagnostic_lifecycle(&shared_uri);
        state.record_package_seed_installed()
    }

    #[test]
    fn source_following_disk_projection_rejects_rewrite_delete_recreate_and_invalid_repair() {
        let tmp = TempDir::new().unwrap();
        let root = tmp.path();
        let helper = root.join("helper.R");
        fs::write(root.join(".Rprofile"), "source(\"helper.R\")\n").unwrap();
        fs::write(&helper, "before <- 1\n").unwrap();
        let capture = || {
            capture_source_following_scans(
                root,
                Default::default(),
                &crate::config_file::CompiledWorkspaceExclusions::default(),
                true,
                Vec::new(),
            )
            .disk
        };
        let routing = crate::package_state::preamble::canonicalize_for_routing(&helper);

        let valid = capture();
        assert!(matches!(
            valid.entries.get(&routing),
            Some(PackageSeedDiskIdentity::Valid { .. })
        ));
        fs::write(&helper, "after_ <- 2\n").unwrap();
        assert!(
            !valid.is_current(),
            "a same-length rewrite must fail the byte-hashed observation"
        );

        let before_delete = capture();
        fs::remove_file(&helper).unwrap();
        assert!(!before_delete.is_current(), "deletion must fail Valid");
        let missing = capture();
        assert_eq!(
            missing.entries.get(&routing),
            Some(&PackageSeedDiskIdentity::Missing)
        );
        fs::write(&helper, "reborn <- 3\n").unwrap();
        assert!(!missing.is_current(), "recreation must fail Missing");

        fs::write(&helper, [0xff, 0xfe, 0xfd]).unwrap();
        let invalid = capture();
        assert!(matches!(
            invalid.entries.get(&routing),
            Some(PackageSeedDiskIdentity::Invalid(Some(_)))
        ));
        fs::write(&helper, "repaired <- 4\n").unwrap();
        assert!(!invalid.is_current(), "valid replacement must fail Invalid");
    }

    #[test]
    fn configuration_seed_retains_committed_post_seed_candidate_for_one_outer_finalization() {
        let tmp = TempDir::new().unwrap();
        let uri = Url::from_file_path(tmp.path().join("consumer.R")).unwrap();
        let mut state = WorldState::new();
        state.open_document(uri.clone(), "consumer <- 1\n", Some(1));
        state
            .begin_open_document_diagnostic_lifecycle(&uri)
            .unwrap();
        let identity = state.record_package_seed_installed();
        let candidates = state.capture_analysis_transfer_candidates([uri.clone()]);
        let mut installed = SeedInstalled {
            identity,
            system_file: None,
            deferred_system_file: None,
            post_seed_candidates: Vec::new(),
            deferred_post_seed: None,
        };

        retain_post_seed_refresh_outcome(
            &mut installed,
            PostSeedRefreshOutcome::Committed(candidates),
        );
        assert_eq!(installed.post_seed_candidates.len(), 1);
        let tickets = finalize_analysis_handoff_candidates_or_fallback(
            &mut state,
            Vec::new(),
            installed.post_seed_candidates,
            Vec::new(),
        );
        assert_eq!(tickets.len(), 1);
        assert_eq!(tickets[0].uri, uri);
        assert_eq!(state.analysis_revalidation_reservation_count, 1);
        assert_eq!(
            state.diagnostics_gate.force_republish_count_for_test(&uri),
            1,
            "the configuration outer finalizer owns the committed candidate exactly once"
        );
    }

    #[test]
    fn post_seed_owner_registration_never_overwrites_a_different_identity() {
        let mut state = WorldState::new();
        let first = state.record_package_seed_installed();
        let second = state.record_package_seed_installed();
        assert_eq!(
            state.begin_post_seed_refresh_retry(first),
            PostSeedRefreshOwnerRegistration::Added
        );
        assert_eq!(
            state.begin_post_seed_refresh_retry(first),
            PostSeedRefreshOwnerRegistration::ExistingSame
        );
        assert_eq!(
            state.begin_post_seed_refresh_retry(second),
            PostSeedRefreshOwnerRegistration::ExistingDifferent(first)
        );
        assert_eq!(state.post_seed_refresh_retry_owner(), Some(first));
        state.complete_post_seed_refresh_retry(first);
        assert_eq!(
            state.begin_post_seed_refresh_retry(second),
            PostSeedRefreshOwnerRegistration::Added
        );
        assert_eq!(state.post_seed_refresh_retry_owner(), Some(second));

        let mut split_state = WorldState::new();
        let routing_owner = split_state.record_package_seed_installed();
        let post_seed_owner = split_state.record_package_seed_installed();
        assert!(split_state.begin_system_file_seed_retry(routing_owner));
        assert_eq!(
            split_state.begin_post_seed_refresh_retry_with_system_dependency(post_seed_owner, true),
            PostSeedRefreshOwnerRegistration::ExistingDifferent(routing_owner)
        );
        assert_eq!(split_state.post_seed_refresh_retry_owner(), None);
        assert_eq!(
            split_state.system_file_seed_retry_owner(),
            Some(routing_owner)
        );
    }

    #[tokio::test]
    async fn combined_post_seed_projection_rejects_both_halves_on_basis_drift() {
        let tmp = TempDir::new().unwrap();
        let root = tmp.path().to_path_buf();
        fs::create_dir_all(root.join("tests/testthat")).unwrap();
        fs::create_dir_all(root.join("scripts")).unwrap();
        fs::write(
            root.join("DESCRIPTION"),
            "Package: combinedtail\nVersion: 0.0.1\nSuggests: testthat\n",
        )
        .unwrap();
        fs::write(root.join(".Rprofile"), "source(\"scripts/shared.R\")\n").unwrap();
        let preamble = root.join("tests/testthat/helper-project.R");
        fs::write(&preamble, "source(\"../../scripts/shared.R\")\n").unwrap();
        fs::write(root.join("scripts/shared.R"), "disk_shared <- 1\n").unwrap();
        let rprofile_uri = Url::from_file_path(root.join(".Rprofile")).unwrap();
        let preamble_uri = Url::from_file_path(&preamble).unwrap();
        let mut state = WorldState::new();
        let identity =
            establish_combined_post_seed_fixture(&mut state, &root, &rprofile_uri, &preamble_uri);

        let captured = capture_combined_post_seed_refresh(
            &state,
            &root,
            CombinedPostSeedRefreshOwnership::ForegroundExact(identity),
        )
        .expect("both tails are live");
        let derived =
            derive_combined_post_seed_refresh(captured).expect("both scans change the seed");
        state.package_inputs.rprofile_symbols =
            std::collections::BTreeSet::from(["newer_profile_owner".to_string()]);
        state.package_inputs.preamble_sourced_symbols.insert(
            preamble.clone(),
            std::collections::BTreeSet::from(["newer_preamble_owner".to_string()]),
        );
        state.record_package_input_mutation();

        assert!(
            state
                .try_install_prepared_package_projection(&derived.basis, derived.package)
                .is_err(),
            "one stale basis must veto the complete Rprofile+preamble projection"
        );
        assert_eq!(
            state.package_inputs.rprofile_symbols,
            std::collections::BTreeSet::from(["newer_profile_owner".to_string()])
        );
        assert_eq!(
            state.package_inputs.preamble_sourced_symbols.get(&preamble),
            Some(&std::collections::BTreeSet::from([
                "newer_preamble_owner".to_string()
            ]))
        );
    }

