    /// When the two immediate routing attempts are exhausted, the delayed
    /// owner must retain exact record+diagnostic identities. A current
    /// successor may inherit and finalize the still-current DESCRIPTION
    /// subject first, but closing and reopening another candidate must not
    /// redirect the old transaction's marker or reservation into its new
    /// lifecycle.
    #[tokio::test(start_paused = true)]
    async fn deferred_description_edit_drops_close_reopen_candidate_lifecycle() {
        let tmp = TempDir::new().unwrap();
        fs::create_dir(tmp.path().join("inst")).unwrap();
        fs::create_dir(tmp.path().join("R")).unwrap();
        let disk_description = "Package: diskpkg\nVersion: 1.0\n";
        fs::write(tmp.path().join("DESCRIPTION"), disk_description).unwrap();
        fs::write(tmp.path().join("inst/helper.R"), "helper_value <- 1\n").unwrap();

        let svc = service_in_synthetic_package_workspace(&tmp).await;
        let backend = svc.inner();
        let exclusions = crate::config_file::CompiledWorkspaceExclusions::default();
        {
            let mut state = backend.state.write().await;
            initialize_package_inputs_from_state_with_exclusions(
                &mut state,
                tmp.path().to_path_buf(),
                Some(Arc::from(disk_description)),
                None,
                Default::default(),
                None,
                None,
                &exclusions,
            );
            state.cross_file_config.max_revalidations_per_trigger = 1;
            state.cross_file_config.revalidation_debounce_ms = 60_000;
            state.library_routing_derivation_on_tokio_for_test = true;
        }

        let description_uri = Url::from_file_path(tmp.path().join("DESCRIPTION")).unwrap();
        let consumer_uri = Url::from_file_path(tmp.path().join("R/consumer.R")).unwrap();
        let helper_uri = Url::from_file_path(tmp.path().join("inst/helper.R")).unwrap();
        let consumer_text =
            "source(system.file(\"helper.R\", package = \"bufferpkg\"))\nhelper_value\n";
        open_doc(backend, &consumer_uri, "r", 1, consumer_text).await;
        open_doc(backend, &description_uri, "r", 1, disk_description).await;
        let (immediate_attempt_baseline, successor_finalization_baseline) = {
            let mut state = backend.state.write().await;
            state.system_file_test_reject_remaining = 2;
            (
                state.system_file_test_commit_attempts,
                state.analysis_transfer_finalization_count_for_test(),
            )
        };

        let expected_immediate_attempts = immediate_attempt_baseline + 2;
        change_doc(
            backend,
            &description_uri,
            2,
            "Package: bufferpkg\nVersion: 2.0\n",
        )
        .await;
        assert_eq!(
            backend.state.read().await.system_file_test_commit_attempts,
            expected_immediate_attempts,
            "the edit transaction must exhaust exactly its two immediate attempts"
        );

        let delayed_pause = backend
            .state
            .read()
            .await
            .system_file_pre_derivation_test_pause
            .arm(Url::parse("raven-test://system-file-pre-derivation").unwrap());
        close_doc(backend, &consumer_uri).await;
        open_doc(backend, &consumer_uri, "r", 1, consumer_text).await;
        assert!(
            wait_for_state(backend, 5_000, |state| {
                state.analysis_transfer_finalization_count_for_test()
                    > successor_finalization_baseline
            })
            .await,
            "the close/reopen successor must finish its inherited finalization before snapshot"
        );
        delayed_pause.wait_arrived().await;

        let (reopened_epoch, reservations, markers, description_markers) = {
            let state = backend.state.read().await;
            assert!(
                has_dependency_edge(&state, &consumer_uri, &helper_uri),
                "the reopened lifecycle must resolve against current buffer package identity"
            );
            (
                state
                    .diagnostics_gate
                    .current_epoch(&consumer_uri)
                    .expect("the reopened document has a diagnostic lifecycle"),
                state.analysis_revalidation_reservation_count,
                state
                    .diagnostics_gate
                    .force_republish_count_for_test(&consumer_uri),
                state
                    .diagnostics_gate
                    .force_republish_count_for_test(&description_uri),
            )
        };
        delayed_pause.release();
        assert!(
            wait_for_state(backend, 5_000, |state| {
                state.system_file_test_commit_attempts >= immediate_attempt_baseline + 3
                    && state.post_seed_refresh_retry_owner().is_none()
                    && state.system_file_seed_retry_owner().is_none()
            })
            .await,
            "the delayed exact owner must converge and retire its retained bundle"
        );

        let state = backend.state.read().await;
        assert_eq!(
            state.diagnostics_gate.current_epoch(&consumer_uri),
            Some(reopened_epoch),
            "delayed convergence must not replace the reopened lifecycle"
        );
        assert_eq!(
            state.analysis_revalidation_reservation_count, reservations,
            "the successor already finalized DESCRIPTION; the stale delayed candidate adds nothing"
        );
        assert_eq!(
            state
                .diagnostics_gate
                .force_republish_count_for_test(&consumer_uri),
            markers,
            "the stale outer candidate must not mark the reopened lifecycle"
        );
        assert_eq!(
            state
                .diagnostics_gate
                .force_republish_count_for_test(&description_uri),
            description_markers,
            "the surviving DESCRIPTION subject must keep its no-force reservation policy"
        );
        let settled_attempts = state.system_file_test_commit_attempts;
        drop(state);
        tokio::time::advance(std::time::Duration::from_secs(120)).await;
        tokio::task::yield_now().await;
        assert_eq!(
            backend.state.read().await.system_file_test_commit_attempts,
            settled_attempts,
            "settled routing ownership must not leak a later commit attempt"
        );
    }

    /// A newer symlink alias must keep its own graph node fresh without
    /// overwriting the canonical graph node owned by the exact canonical open
    /// buffer.
    #[cfg(unix)]
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn non_authoritative_alias_change_does_not_overwrite_canonical_graph_root() {
        let tmp = TempDir::new().unwrap();
        fs::write(tmp.path().join("child.R"), "child_fn <- function() 1\n").unwrap();
        fs::write(tmp.path().join("extra.R"), "extra_fn <- function() 2\n").unwrap();
        std::os::unix::fs::symlink(tmp.path().join("child.R"), tmp.path().join("link.R")).unwrap();

        let (svc, child_uri) =
            open_in_quiescent_workspace(&tmp, "child.R", "r", "child_fn <- function() 1\n").await;
        let backend = svc.inner();
        let link_uri = Url::from_file_path(tmp.path().join("link.R")).unwrap();
        let extra_uri = Url::from_file_path(tmp.path().join("extra.R")).unwrap();

        open_doc(backend, &link_uri, "r", 1, "child_fn <- function() 1\n").await;
        change_doc(
            backend,
            &link_uri,
            2,
            "source(\"extra.R\")\nchild_fn <- function() 1\n",
        )
        .await;

        let state = backend.state.read().await;
        assert_eq!(
            state.open_document_uri_for_authoritative_uri(&child_uri),
            Some(child_uri.clone()),
            "exact canonical open URI must outrank symlink aliases"
        );
        assert!(
            state
                .cross_file_graph
                .get_dependencies(&link_uri)
                .iter()
                .any(|edge| edge.to == extra_uri),
            "the non-authoritative alias keeps its own graph node fresh"
        );
        assert!(
            !state
                .cross_file_graph
                .get_dependencies(&child_uri)
                .iter()
                .any(|edge| edge.to == extra_uri),
            "the non-authoritative alias must not overwrite canonical graph edges"
        );
    }

    /// When the authoritative alias closes, the canonical graph node must switch
    /// to the remaining authoritative alias instead of waiting for a future edit.
    #[cfg(unix)]
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn closing_authoritative_alias_remirrors_remaining_alias_to_canonical_root() {
        let tmp = TempDir::new().unwrap();
        fs::write(tmp.path().join("child.R"), "child_fn <- function() 1\n").unwrap();
        fs::write(tmp.path().join("extra.R"), "extra_fn <- function() 2\n").unwrap();
        fs::write(tmp.path().join("driver.R"), "driver <- 1\n").unwrap();
        std::os::unix::fs::symlink(tmp.path().join("child.R"), tmp.path().join("link-a.R"))
            .unwrap();
        std::os::unix::fs::symlink(tmp.path().join("child.R"), tmp.path().join("link-b.R"))
            .unwrap();

        let (svc, _driver_uri) =
            open_in_quiescent_workspace(&tmp, "driver.R", "r", "driver <- 1\n").await;
        let backend = svc.inner();
        let child_uri = Url::from_file_path(tmp.path().join("child.R")).unwrap();
        let link_a_uri = Url::from_file_path(tmp.path().join("link-a.R")).unwrap();
        let link_b_uri = Url::from_file_path(tmp.path().join("link-b.R")).unwrap();
        let extra_uri = Url::from_file_path(tmp.path().join("extra.R")).unwrap();

        open_doc(backend, &link_a_uri, "r", 1, "child_fn <- function() 1\n").await;
        open_doc(
            backend,
            &link_b_uri,
            "r",
            1,
            "source(\"extra.R\")\nchild_fn <- function() 1\n",
        )
        .await;
        {
            let state = backend.state.read().await;
            assert_eq!(
                state.open_document_uri_for_authoritative_uri(&child_uri),
                Some(link_a_uri.clone()),
                "oldest alias should initially own the canonical root"
            );
            assert!(
                !state
                    .cross_file_graph
                    .get_dependencies(&child_uri)
                    .iter()
                    .any(|edge| edge.to == extra_uri),
                "newer non-authoritative alias must not overwrite the canonical root"
            );
        }

        close_doc(backend, &link_a_uri).await;

        let remirrored = wait_for_state(backend, 5_000, |state| {
            state.open_document_uri_for_authoritative_uri(&child_uri) == Some(link_b_uri.clone())
                && state
                    .cross_file_graph
                    .get_dependencies(&child_uri)
                    .iter()
                    .any(|edge| edge.to == extra_uri)
        })
        .await;
        assert!(
            remirrored,
            "closing the authoritative alias must remirror the remaining alias metadata"
        );
    }

    // ====================================================================
    // did_close disk resync (issue #558): closing a buffer must converge
    // the cross-file graph/index back to disk truth, discarding topology
    // derived from unsaved buffer edits.
    // ====================================================================

    /// Issue #558 test 1: an unsaved `source()` edge added in the buffer
    /// must disappear from the graph when the document closes — the resync
    /// reverts to disk topology (which has no such edge).
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn close_after_unsaved_added_source_edge_reverts_to_disk_topology() {
        let tmp = TempDir::new().unwrap();
        fs::write(tmp.path().join("helper.R"), "x <- 1\n").unwrap();
        fs::write(tmp.path().join("extra.R"), "extra_fn <- function() 2\n").unwrap();
        let (svc, helper_uri) =
            open_in_quiescent_workspace(&tmp, "helper.R", "r", "x <- 1\n").await;
        let backend = svc.inner();
        let extra_uri = Url::from_file_path(tmp.path().join("extra.R")).unwrap();

        // Unsaved buffer edit adds a source() edge; the open buffer is
        // authoritative, so the graph gains it.
        change_doc(backend, &helper_uri, 2, "source(\"extra.R\")\nx <- 1\n").await;
        {
            let state = backend.state.read().await;
            assert!(
                state
                    .cross_file_graph
                    .get_dependencies(&helper_uri)
                    .iter()
                    .any(|e| e.to == extra_uri),
                "unsaved buffer edit must add the helper -> extra edge"
            );
        }

        close_doc(backend, &helper_uri).await;

        let reverted = wait_for_state(backend, 5_000, |state| {
            !state
                .cross_file_graph
                .get_dependencies(&helper_uri)
                .iter()
                .any(|e| e.to == extra_uri)
        })
        .await;
        assert!(
            reverted,
            "close must revert the buffer-only source() edge to disk topology"
        );
        let state = backend.state.read().await;
        let meta = state
            .workspace_index
            .get_metadata(&helper_uri)
            .expect("close resync must install disk-derived index metadata");
        assert!(
            meta.sources.is_empty(),
            "index metadata must reflect the on-disk content (no source() call)"
        );
    }

    /// The resync gate keys off the tracked document's `file_type`, not the
    /// URI extension, so extension-less R documents like `.Rprofile` get the
    /// close-time resync too: a buffer-only source() edge in an unsaved
    /// `.Rprofile` must revert on close.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn close_rprofile_reverts_buffer_only_source_edge() {
        let tmp = TempDir::new().unwrap();
        fs::write(tmp.path().join(".Rprofile"), "options(digits = 3)\n").unwrap();
        fs::write(tmp.path().join("extra.R"), "extra_fn <- function() 2\n").unwrap();
        let (svc, rprofile_uri) =
            open_in_quiescent_workspace(&tmp, ".Rprofile", "r", "options(digits = 3)\n").await;
        let backend = svc.inner();
        let extra_uri = Url::from_file_path(tmp.path().join("extra.R")).unwrap();

        change_doc(
            backend,
            &rprofile_uri,
            2,
            "source(\"extra.R\")\noptions(digits = 3)\n",
        )
        .await;
        {
            let state = backend.state.read().await;
            assert!(
                state
                    .cross_file_graph
                    .get_dependencies(&rprofile_uri)
                    .iter()
                    .any(|e| e.to == extra_uri),
                "unsaved .Rprofile edit must add the edge"
            );
        }

        close_doc(backend, &rprofile_uri).await;

        let reverted = wait_for_state(backend, 5_000, |state| {
            !state
                .cross_file_graph
                .get_dependencies(&rprofile_uri)
                .iter()
                .any(|e| e.to == extra_uri)
        })
        .await;
        assert!(
            reverted,
            ".Rprofile close must revert the buffer-only source() edge to disk topology"
        );
    }

    /// The resync enriches disk metadata with the parent's inherited working
    /// directory before committing, matching `did_open`/`did_change`: closing
    /// a `# raven: sourced-by` child whose source() paths resolve through the
    /// parent's `# raven: cd` must keep those edges rather than dropping to
    /// file-relative resolution.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn close_resync_preserves_inherited_working_directory_edges() {
        let tmp = TempDir::new().unwrap();
        fs::create_dir(tmp.path().join("data")).unwrap();
        fs::create_dir(tmp.path().join("scripts")).unwrap();
        fs::write(
            tmp.path().join("parent.R"),
            "# raven: cd data\nsource(\"../scripts/child.R\")\n",
        )
        .unwrap();
        fs::write(
            tmp.path().join("data").join("helper.R"),
            "helper_fn <- function() 1\n",
        )
        .unwrap();
        let child_disk = "# raven: sourced-by ../parent.R\nsource(\"helper.R\")\n";
        fs::write(tmp.path().join("scripts").join("child.R"), child_disk).unwrap();

        let (svc, child_uri) =
            open_in_quiescent_workspace(&tmp, "scripts/child.R", "r", child_disk).await;
        let backend = svc.inner();
        let helper_uri = Url::from_file_path(tmp.path().join("data").join("helper.R")).unwrap();

        // did_open enriched the buffer's metadata with the parent's `cd`, so
        // the child's source("helper.R") resolves to data/helper.R (never
        // scripts/helper.R, which does not exist).
        {
            let state = backend.state.read().await;
            assert!(
                state
                    .cross_file_graph
                    .get_dependencies(&child_uri)
                    .iter()
                    .any(|e| e.to == helper_uri),
                "open must resolve the child's source() through the inherited working directory"
            );
        }
        {
            let state = backend.state.write().await;
            state.workspace_index.invalidate(&child_uri);
            state.cross_file_file_cache.invalidate(&child_uri);
            assert!(
                !state.workspace_index.contains(&child_uri),
                "force the no-shadow fresh-disk close path"
            );
        }

        close_doc(backend, &child_uri).await;

        // Wait for the resync to install disk-derived index metadata (the
        // edge itself is unchanged here, so it cannot signal completion).
        let resynced = wait_for_state(backend, 5_000, |state| {
            state.workspace_index.get_metadata(&child_uri).is_some()
        })
        .await;
        assert!(
            resynced,
            "close resync must install index metadata for the child"
        );
        let state = backend.state.read().await;
        assert!(
            state
                .cross_file_graph
                .get_dependencies(&child_uri)
                .iter()
                .any(|e| e.to == helper_uri),
            "close resync must keep resolving through the inherited working directory"
        );
    }

    /// Issue #558 test 2: a `source()` edge removed by an unsaved buffer
    /// edit must be restored from disk when the document closes.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn close_after_unsaved_removed_edge_restores_disk_edge() {
        let tmp = TempDir::new().unwrap();
        let disk = "source(\"extra.R\")\nx <- 1\n";
        fs::write(tmp.path().join("helper.R"), disk).unwrap();
        fs::write(tmp.path().join("extra.R"), "extra_fn <- function() 2\n").unwrap();
        let (svc, helper_uri) = open_in_quiescent_workspace(&tmp, "helper.R", "r", disk).await;
        let backend = svc.inner();
        let extra_uri = Url::from_file_path(tmp.path().join("extra.R")).unwrap();

        // Unsaved buffer edit removes the source() line; the edge drops.
        change_doc(backend, &helper_uri, 2, "x <- 1\n").await;
        {
            let state = backend.state.read().await;
            assert!(
                !state
                    .cross_file_graph
                    .get_dependencies(&helper_uri)
                    .iter()
                    .any(|e| e.to == extra_uri),
                "unsaved buffer edit must drop the helper -> extra edge"
            );
        }

        close_doc(backend, &helper_uri).await;

        let restored = wait_for_state(backend, 5_000, |state| {
            state
                .cross_file_graph
                .get_dependencies(&helper_uri)
                .iter()
                .any(|e| e.to == extra_uri)
        })
        .await;
        assert!(
            restored,
            "close must restore the on-disk source() edge the unsaved edit removed"
        );
    }

    /// Issue #558 test 3 (deterministic half): when the URI is an open
    /// document, `resync_file_from_disk` must return `Vetoed` and mutate
    /// nothing — the open buffer's state stays authoritative. (With the doc
    /// open for the whole call this exercises the preflight veto; the
    /// commit-time veto is the same check replayed under the write lock, and
    /// the close-then-reopen e2e test covers the racing case.)
    #[tokio::test]
    async fn closed_resync_preserves_import_workspace_fallback_edge() {
        let tmp = TempDir::new().unwrap();
        fs::create_dir(tmp.path().join("scripts")).unwrap();
        fs::write(tmp.path().join("anchor.R"), "anchor <- 1\n").unwrap();
        fs::write(tmp.path().join("mod.R"), "public <- function() 1\n").unwrap();
        fs::write(
            tmp.path().join("scripts/main.R"),
            "import::here('mod.R', public)\npublic()\n",
        )
        .unwrap();
        let (svc, _anchor_uri) =
            open_in_quiescent_workspace(&tmp, "anchor.R", "r", "anchor <- 1\n").await;
        let backend = svc.inner();
        let importer_uri = Url::from_file_path(tmp.path().join("scripts/main.R")).unwrap();
        let module_uri = Url::from_file_path(tmp.path().join("mod.R")).unwrap();

        let outcome = resync_file_from_disk(
            &backend.state,
            &importer_uri,
            None,
            None,
            true,
            None,
            ResyncCommitMode::Immediate,
        )
        .await;
        assert!(matches!(outcome, ResyncOutcome::Updated { .. }));
        let state = backend.state.read().await;
        assert!(
            state
                .cross_file_graph
                .get_dependencies(&importer_uri)
                .iter()
                .any(|edge| edge.to == module_uri && edge.is_selective_module()),
            "closed resync must retain the workspace-root selective-module edge"
        );
    }

    #[tokio::test]
    async fn resync_vetoes_commit_when_document_is_open() {
        let tmp = TempDir::new().unwrap();
        // Disk has a source() edge; the open buffer does NOT.
        fs::write(tmp.path().join("helper.R"), "source(\"extra.R\")\nx <- 1\n").unwrap();
        fs::write(tmp.path().join("extra.R"), "extra_fn <- function() 2\n").unwrap();
        let (svc, helper_uri) =
            open_in_quiescent_workspace(&tmp, "helper.R", "r", "x <- 1\n").await;
        let backend = svc.inner();
        let extra_uri = Url::from_file_path(tmp.path().join("extra.R")).unwrap();

        let outcome = resync_file_from_disk(
            &backend.state,
            &helper_uri,
            None,
            None,
            true,
            None,
            ResyncCommitMode::Immediate,
        )
        .await;
        assert!(
            matches!(outcome, ResyncOutcome::Vetoed),
            "resync must veto while the document is open"
        );
        let state = backend.state.read().await;
        assert!(
            !state
                .cross_file_graph
                .get_dependencies(&helper_uri)
                .iter()
                .any(|e| e.to == extra_uri),
            "vetoed resync must not install disk-derived edges over buffer state"
        );
    }

    #[tokio::test]
    async fn resync_restores_open_parent_when_other_incoming_edges_do_not_lend_scope() {
        let tmp = TempDir::new().unwrap();
        let parent = "source(\"helper.R\")\nparent_value <- 1\n";
        fs::write(tmp.path().join("parent.R"), parent).unwrap();
        fs::write(tmp.path().join("helper.R"), "helper_value <- 1\n").unwrap();

        let (svc, parent_uri) = open_in_quiescent_workspace(&tmp, "parent.R", "r", parent).await;
        let backend = svc.inner();
        let helper_uri = Url::from_file_path(tmp.path().join("helper.R")).unwrap();
        let excluded_uri = Url::from_file_path(tmp.path().join("excluded.R")).unwrap();
        let selective_uri = Url::from_file_path(tmp.path().join("selective.R")).unwrap();

        {
            let mut state = backend.state.write().await;
            // Simulate the exists -> missing half: removing the helper strips
            // parent-owned incoming edges, but the open parent's metadata still
            // has the source() entry that resync must replay.
            state.cross_file_graph.remove_file(&helper_uri);

            let workspace_root = state.workspace_folders.first().cloned();
            let excluded_meta = crate::cross_file::CrossFileMetadata {
                sources: vec![crate::cross_file::types::ForwardSource {
                    path: "helper.R".to_string(),
                    line: 0,
                    column: 0,
                    ..Default::default()
                }],
                ..Default::default()
            };
            state.cross_file_graph.update_file(
                &excluded_uri,
                &excluded_meta,
                workspace_root.as_ref(),
                |_| None,
            );
            state
                .cross_file_graph
                .make_forward_edges_non_lending(&excluded_uri);

            let mut selective_meta = crate::cross_file::extract_metadata("box::use(./helper)\n");
            crate::cross_file::enrich_box_import_resolutions(&mut selective_meta, &selective_uri);
            state.cross_file_graph.update_file(
                &selective_uri,
                &selective_meta,
                workspace_root.as_ref(),
                |_| None,
            );

            let incoming = state.cross_file_graph.get_dependents(&helper_uri);
            assert_eq!(
                incoming.len(),
                2,
                "precondition: only non-lending ordinary and selective edges remain"
            );
            assert!(
                incoming
                    .iter()
                    .any(|edge| edge.from == excluded_uri && edge.non_lending),
                "precondition: retained ordinary incoming edge is non-lending"
            );
            assert!(
                incoming.iter().any(|edge| {
                    edge.from == selective_uri
                        && edge.is_selective_module()
                        && !edge.non_lending
                        && !edge.lends_scope()
                }),
                "precondition: a selective edge is graph-visible but does not lend scope"
            );
        }

        let outcome = resync_file_from_disk(
            &backend.state,
            &helper_uri,
            None,
            None,
            true,
            None,
            ResyncCommitMode::Immediate,
        )
        .await;
        assert!(
            matches!(outcome, ResyncOutcome::Updated { .. }),
            "helper resync should commit disk state"
        );

        let state = backend.state.read().await;
        let incoming = state.cross_file_graph.get_dependents(&helper_uri);
        assert!(
            incoming
                .iter()
                .any(|edge| edge.from == parent_uri && !edge.non_lending),
            "a non-lending excluded edge must not suppress restoration of the real open parent"
        );
        assert!(
            incoming
                .iter()
                .any(|edge| edge.from == excluded_uri && edge.non_lending),
            "the excluded consumer's retained edge remains non-lending"
        );
        assert!(
            incoming
                .iter()
                .any(|edge| edge.from == selective_uri && edge.is_selective_module()),
            "the selective consumer's revalidation edge remains present"
        );
    }

    /// The staleness veto: a resync must never overwrite a NEWER snapshot a
    /// concurrent same-file resync already committed (close resync racing a
    /// watched CHANGED event — both open-document vetoes are blind to
    /// freshness). Seeding the file cache with a future-mtime snapshot
    /// simulates the fresher commit having won the race.
    #[tokio::test]
    async fn resync_skips_when_newer_snapshot_already_committed() {
        let tmp = TempDir::new().unwrap();
        // Disk content would add an edge if committed.
        fs::write(tmp.path().join("helper.R"), "source(\"extra.R\")\nx <- 1\n").unwrap();
        fs::write(tmp.path().join("extra.R"), "extra_fn <- function() 2\n").unwrap();
        fs::write(tmp.path().join("other.R"), "y <- 1\n").unwrap();
        let (svc, _other_uri) = open_in_quiescent_workspace(&tmp, "other.R", "r", "y <- 1\n").await;
        let backend = svc.inner();
        let helper_uri = Url::from_file_path(tmp.path().join("helper.R")).unwrap();
        let extra_uri = Url::from_file_path(tmp.path().join("extra.R")).unwrap();

        // Simulate a concurrent resync having committed FRESHER disk state:
        // a cache snapshot whose mtime is ahead of the on-disk file's.
        let newer_content = "newer <- 1\n".to_string();
        {
            let state = backend.state.read().await;
            state.cross_file_file_cache.insert(
                helper_uri.clone(),
                crate::cross_file::file_cache::FileSnapshot {
                    mtime: std::time::SystemTime::now() + std::time::Duration::from_secs(3600),
                    size: newer_content.len() as u64,
                    content_hash: None,
                },
                newer_content.clone(),
            );
        }

        let outcome = resync_file_from_disk(
            &backend.state,
            &helper_uri,
            None,
            None,
            true,
            None,
            ResyncCommitMode::Immediate,
        )
        .await;
        assert!(
            matches!(outcome, ResyncOutcome::Skipped),
            "an older disk read must not overwrite a newer committed snapshot"
        );
        let state = backend.state.read().await;
        assert_eq!(
            state.cross_file_file_cache.get(&helper_uri).as_deref(),
            Some(newer_content.as_str()),
            "the fresher cached content must survive the stale resync"
        );
        assert!(
            !state
                .cross_file_graph
                .get_dependencies(&helper_uri)
                .iter()
                .any(|e| e.to == extra_uri),
            "the stale read's edges must not be committed"
        );
    }

    /// Opening a document invalidates its closed-file cache entry, so a
    /// poisoned (newer-mtime) snapshot from before the open cannot wrongly
    /// win the staleness veto at the next close — e.g. a `git checkout`
    /// restoring older mtimes while the buffer was open, when watcher
    /// events (and their invalidation) are skipped.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn open_clears_cached_snapshot_so_close_resync_commits() {
        use tower_lsp::lsp_types::{DidCloseTextDocumentParams, TextDocumentIdentifier};

        let tmp = TempDir::new().unwrap();
        fs::write(tmp.path().join("helper.R"), "x <- 1\n").unwrap();
        fs::write(tmp.path().join("extra.R"), "extra_fn <- function() 2\n").unwrap();
        fs::write(tmp.path().join("other.R"), "y <- 1\n").unwrap();
        let (svc, _other) = open_in_quiescent_workspace(&tmp, "other.R", "r", "y <- 1\n").await;
        let backend = svc.inner();
        let helper_uri = Url::from_file_path(tmp.path().join("helper.R")).unwrap();
        let extra_uri = Url::from_file_path(tmp.path().join("extra.R")).unwrap();

        // Poison the cache with a future-mtime snapshot (as a fresher commit
        // would leave), then open the file — the open must clear it.
        {
            let state = backend.state.read().await;
            state.cross_file_file_cache.insert(
                helper_uri.clone(),
                crate::cross_file::file_cache::FileSnapshot {
                    mtime: std::time::SystemTime::now() + std::time::Duration::from_secs(3600),
                    size: 1,
                    content_hash: None,
                },
                "poisoned <- 1\n".to_string(),
            );
        }
        open_doc(backend, &helper_uri, "r", 1, "x <- 1\n").await;

        // Simulate the checkout: disk now has an edge; its mtime is "older"
        // than the poisoned snapshot would have been.
        fs::write(tmp.path().join("helper.R"), "source(\"extra.R\")\nx <- 1\n").unwrap();
        backend
            .did_close(DidCloseTextDocumentParams {
                text_document: TextDocumentIdentifier {
                    uri: helper_uri.clone(),
                },
            })
            .await;

        let committed = wait_for_state(backend, 5_000, |state| {
            state
                .cross_file_graph
                .get_dependencies(&helper_uri)
                .iter()
                .any(|e| e.to == extra_uri)
        })
        .await;
        assert!(
            committed,
            "the close resync must commit disk state — the pre-open snapshot must not veto it"
        );
    }

    /// A watched CHANGED that reads transiently-invalid UTF-8 (a non-atomic
    /// external write in progress) must NOT remove the file's cross-file
    /// state: removal would strip a closed parent's incoming edge, which
    /// nothing could restore. It skips the immediate removal; issue #564's
    /// delayed retry is allowed to converge only after this transient window.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn watched_transient_invalid_encoding_does_not_remove_state() {
        use tower_lsp::lsp_types::{DidChangeWatchedFilesParams, FileChangeType, FileEvent};

        let tmp = TempDir::new().unwrap();
        fs::write(tmp.path().join("child.R"), "child_fn <- function() 1\n").unwrap();
        let parent = "source(\"child.R\")\nchild_fn()\n";
        fs::write(tmp.path().join("parent.R"), parent).unwrap();
        let (svc, parent_uri) = open_in_quiescent_workspace(&tmp, "parent.R", "r", parent).await;
        let backend = svc.inner();
        let child_uri = Url::from_file_path(tmp.path().join("child.R")).unwrap();
        {
            let state = backend.state.read().await;
            assert!(
                state
                    .cross_file_graph
                    .get_dependencies(&parent_uri)
                    .iter()
                    .any(|e| e.to == child_uri),
                "precondition: parent -> child edge exists"
            );
        }

        // Mid-write garbage on disk, then the watcher fires.
        std::fs::write(tmp.path().join("child.R"), [0x78u8, 0x80, 0x79]).unwrap();
        backend
            .did_change_watched_files(DidChangeWatchedFilesParams {
                changes: vec![FileEvent {
                    uri: child_uri.clone(),
                    typ: FileChangeType::CHANGED,
                }],
            })
            .await;

        // Give the async resync time to (incorrectly) act, then assert the
        // edge survived the transient garbage.
        tokio::time::sleep(std::time::Duration::from_millis(400)).await;
        let state = backend.state.read().await;
        assert!(
            state
                .cross_file_graph
                .get_dependencies(&parent_uri)
                .iter()
                .any(|e| e.to == child_uri),
            "transiently-undecodable watched content must not strip the parent's edge"
        );
    }

    /// A watched CHANGED on the package `R/` directory must still run the
    /// package-input directory rescan even though the cross-file file resync
    /// skips after failing to read the directory as source text.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn watched_changed_on_package_r_directory_rescans_r_files() {
        let tmp = TempDir::new().unwrap();
        let r_dir = tmp.path().join("R");
        fs::create_dir(&r_dir).unwrap();
        fs::write(tmp.path().join("main.R"), "x <- 1\n").unwrap();
        let (svc, _main_uri) =
            open_in_synthetic_package_workspace(&tmp, "main.R", "r", "x <- 1\n").await;
        let backend = svc.inner();
        backend.state.write().await.package_inputs.workspace_root = Some(tmp.path().to_path_buf());

        let helper_path = r_dir.join("helper.R");
        let helper = "helper_fn <- function() 1\n";
        fs::write(&helper_path, helper).unwrap();

        let r_dir_uri = Url::from_file_path(&r_dir).unwrap();
        send_watched_change(backend, &r_dir_uri).await;

        let rescanned = wait_for_state(backend, 5_000, |state| {
            state
                .package_inputs
                .r_files
                .get(&helper_path)
                .is_some_and(|input| input.text.as_ref() == helper)
        })
        .await;
        assert!(
            rescanned,
            "a directory-only watched event on R/ must hydrate new package R files"
        );
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn watched_mixed_package_inputs_commit_from_one_full_projection() {
        let tmp = TempDir::new().unwrap();
        for directory in ["R", "data", "data-raw", "inst", "tests/testthat", "scripts"] {
            fs::create_dir_all(tmp.path().join(directory)).unwrap();
        }
        let description = tmp.path().join("DESCRIPTION");
        let namespace = tmp.path().join("NAMESPACE");
        let r_file = tmp.path().join("R/new.R");
        let dataset = tmp.path().join("data/new.csv");
        let data_raw = tmp.path().join("data-raw/new.R");
        let preamble = tmp.path().join("tests/testthat/helper-project.R");
        let preamble_source = tmp.path().join("scripts/preamble.R");
        let system_helper = tmp.path().join("inst/helper.R");
        fs::write(&description, "Package: newpkg\nVersion: 1.0.0\n").unwrap();
        fs::write(&namespace, "export(new_fun)\n").unwrap();
        fs::write(&r_file, "new_fun <- function() 1\n").unwrap();
        fs::write(&dataset, "value\n1\n").unwrap();
        fs::write(
            &data_raw,
            "usethis::use_data(new_internal, internal = TRUE)\n",
        )
        .unwrap();
        fs::write(&preamble, "source(\"../../scripts/preamble.R\")\n").unwrap();
        fs::write(&preamble_source, "preamble_value <- 1\n").unwrap();
        fs::write(&system_helper, "system_helper <- 1\n").unwrap();
        let main = concat!(
            "source(system.file(\"helper.R\", package = \"newpkg\"))\n",
            "new_fun()\n",
        );
        fs::write(tmp.path().join("main.R"), main).unwrap();

        let (svc, main_uri) = open_in_synthetic_package_workspace(&tmp, "main.R", "r", main).await;
        let backend = svc.inner();
        let sibling_uri = Url::from_file_path(tmp.path().join("R/sibling.R")).unwrap();
        open_doc(backend, &sibling_uri, "r", 1, "sibling <- 1\n").await;
        {
            let mut state = backend.state.write().await;
            state.package_inputs.workspace_root = Some(tmp.path().to_path_buf());
            state.package_inputs.package_mode = crate::cross_file::config::PackageMode::Auto;
            state.system_file_test_reject_remaining = 2;
            state.cross_file_config.max_revalidations_per_trigger = 1;
        }
        let routing_before = {
            let state = backend.state.read().await;
            state.system_file_routing_owner_generation()
        };
        let handoff = backend
            .state
            .read()
            .await
            .watched_final_handoff_test_capture
            .arm_for(main_uri.as_str());
        backend
            .did_change_watched_files(DidChangeWatchedFilesParams {
                changes: [
                    &description,
                    &namespace,
                    &r_file,
                    &dataset,
                    &data_raw,
                    &preamble,
                    &preamble_source,
                ]
                .into_iter()
                .map(|path| FileEvent {
                    uri: Url::from_file_path(path).unwrap(),
                    typ: FileChangeType::CHANGED,
                })
                .collect(),
            })
            .await;
        let final_handoff =
            wait_final_handoff_payload(backend, &handoff, "watched-package-batch", &[&main_uri])
                .await;

        let converged = wait_for_state(backend, 5_000, |state| {
            state
                .package_state
                .workspace()
                .map(|workspace| workspace.name.as_str())
                == Some("newpkg")
                && state
                    .package_inputs
                    .namespace
                    .as_ref()
                    .is_some_and(|input| input.text.as_ref() == "export(new_fun)\n")
                && state
                    .package_inputs
                    .r_files
                    .get(&r_file)
                    .is_some_and(|input| input.text.as_ref() == "new_fun <- function() 1\n")
                && state.package_inputs.dataset_names.contains("new")
                && state.package_inputs.sysdata_names.contains("new_internal")
                && state
                    .package_inputs
                    .preamble_sourced_symbols
                    .values()
                    .any(|symbols| symbols.contains("preamble_value"))
                && state
                    .cross_file_graph
                    .get_dependencies(&main_uri)
                    .iter()
                    .any(|edge| edge.to == Url::from_file_path(&system_helper).unwrap())
        })
        .await;
        if !converged {
            let state = backend.state.read().await;
            panic!(
                "one watched projection must converge every package-backed input tier: \
                 package={:?}, namespace={}, r_file={}, dataset={}, sysdata={}, preamble={}, \
                 system_edge={}, helper_index={}, attempts={}, sources={:?}, \
                 final_handoff={final_handoff:?}",
                state
                    .package_state
                    .workspace()
                    .map(|workspace| workspace.name.as_str()),
                state.package_inputs.namespace.is_some(),
                state.package_inputs.r_files.contains_key(&r_file),
                state.package_inputs.dataset_names.contains("new"),
                state.package_inputs.sysdata_names.contains("new_internal"),
                state
                    .package_inputs
                    .preamble_sourced_symbols
                    .values()
                    .any(|symbols| symbols.contains("preamble_value")),
                state
                    .cross_file_graph
                    .get_dependencies(&main_uri)
                    .iter()
                    .any(|edge| edge.to == Url::from_file_path(&system_helper).unwrap()),
                state
                    .workspace_index
                    .contains(&Url::from_file_path(&system_helper).unwrap()),
                state.system_file_test_commit_attempts,
                state
                    .documents
                    .get_record(&main_uri)
                    .map(|record| record.metadata().sources.clone()),
            );
        }
        let (routing_after, attempts_after) = {
            let state = backend.state.read().await;
            (
                state.system_file_routing_owner_generation(),
                state.watched_batch_test_commit_attempts,
            )
        };
        assert_eq!(
            final_handoff.outcome,
            crate::state::WatchedFinalHandoffOutcome::Finalized
        );
        assert_ne!(
            routing_after, routing_before,
            "DESCRIPTION package-name installation must own routing convergence"
        );
        assert!(
            final_handoff.reserved.is_empty(),
            "the central watched commit transfers its unmarked fanout"
        );
        assert_eq!(
            final_handoff
                .transferred
                .iter()
                .map(|ticket| &ticket.uri)
                .collect::<Vec<_>>(),
            vec![&sibling_uri],
            "package, system-file, and file candidates must merge into one exact final ticket"
        );
        release_and_wait_final_handoff(
            backend,
            &handoff,
            "watched-package-batch",
            &[&main_uri, &sibling_uri],
        )
        .await;

        send_watched_change(backend, &Url::from_file_path(&description).unwrap()).await;
        assert!(
            wait_for_state(backend, 5_000, |state| {
                state.watched_batch_test_commit_attempts > attempts_after
            })
            .await
        );
        assert_eq!(
            backend
                .state
                .read()
                .await
                .system_file_routing_owner_generation(),
            routing_after,
            "a value-equal DESCRIPTION projection must not mint a routing owner"
        );
    }

    /// Issue #564: when a watched CHANGED read sees invalid UTF-8 and the
    /// delayed retry still sees invalid UTF-8, the file converges like a
    /// deletion instead of retaining its previous graph/index/package state
    /// forever.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn watched_final_invalid_encoding_retry_removes_state() {
        let tmp = TempDir::new().unwrap();
        fs::create_dir(tmp.path().join("R")).unwrap();
        let helper_path = tmp.path().join("R").join("helper.R");
        let helper = "helper_fn <- function() 1\n";
        fs::write(&helper_path, helper).unwrap();
        let main = "source(\"R/helper.R\")\nhelper_fn()\n";
        fs::write(tmp.path().join("main.R"), main).unwrap();
        let (svc, main_uri) = open_in_synthetic_package_workspace(&tmp, "main.R", "r", main).await;
        let backend = svc.inner();
        let helper_uri = Url::from_file_path(&helper_path).unwrap();
        backend.state.write().await.workspace_scan_complete = true;

        let install = resync_file_from_disk(
            &backend.state,
            &helper_uri,
            None,
            None,
            true,
            None,
            ResyncCommitMode::Immediate,
        )
        .await;
        assert!(
            matches!(install, ResyncOutcome::Updated { .. }),
            "precondition: helper disk state installed"
        );
        seed_package_r_file_input(backend, tmp.path(), "R/helper.R", helper).await;
        std::fs::write(&helper_path, [0x78u8, 0x80, 0x79]).unwrap();
        send_watched_change(backend, &helper_uri).await;

        let removed = wait_for_state(backend, 5_000, |state| {
            !state
                .cross_file_graph
                .get_dependencies(&main_uri)
                .iter()
                .any(|e| e.to == helper_uri)
                && state.workspace_index.get_metadata(&helper_uri).is_none()
                && !state.workspace_index.contains(&helper_uri)
                && state.cross_file_file_cache.get(&helper_uri).is_none()
                && !state.package_inputs.r_files.contains_key(&helper_path)
                && !state
                    .watched_file_resync_generations
                    .contains_key(&helper_uri)
                && !snapshot_diagnostics(state, &main_uri).is_empty()
        })
        .await;
        assert!(
            removed,
            "persistent invalid watched bytes must remove graph/index/cache/package state and re-diagnose dependents"
        );
    }

    /// Issue #564: if the delayed retry finds valid UTF-8, it commits that
    /// recovered disk state normally and does not strip the closed parent's
    /// incoming edge.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn watched_invalid_encoding_retry_commits_recovered_valid_state() {
        let tmp = TempDir::new().unwrap();
        fs::create_dir(tmp.path().join("R")).unwrap();
        let helper_path = tmp.path().join("R").join("helper.R");
        let old_helper = "helper_fn <- function() 1\n";
        let recovered_helper = "helper_fn <- function() 2\n";
        fs::write(&helper_path, old_helper).unwrap();
        let parent = "source(\"R/helper.R\")\nhelper_fn()\n";
        fs::write(tmp.path().join("parent.R"), parent).unwrap();
        let (svc, parent_uri) =
            open_in_synthetic_package_workspace(&tmp, "parent.R", "r", parent).await;
        let backend = svc.inner();
        let helper_uri = Url::from_file_path(&helper_path).unwrap();
        close_doc(backend, &parent_uri).await;
        seed_package_r_file_input(backend, tmp.path(), "R/helper.R", old_helper).await;

        std::fs::write(&helper_path, [0x78u8, 0x80, 0x79]).unwrap();
        send_watched_change(backend, &helper_uri).await;

        // Let the immediate watched resync observe the invalid bytes and
        // schedule its one-shot retry, then finish the non-atomic write.
        tokio::time::sleep(std::time::Duration::from_millis(200)).await;
        fs::write(&helper_path, recovered_helper).unwrap();

        let recovered = wait_for_state(backend, 5_000, |state| {
            state.cross_file_file_cache.get(&helper_uri).as_deref() == Some(recovered_helper)
                && state
                    .package_inputs
                    .r_files
                    .get(&helper_path)
                    .is_some_and(|input| input.text.as_ref() == recovered_helper)
                && state
                    .cross_file_graph
                    .get_dependencies(&parent_uri)
                    .iter()
                    .any(|e| e.to == helper_uri)
        })
        .await;
        assert!(
            recovered,
            "recovered watched bytes must commit normally and keep the closed parent edge"
        );
    }

