    /// Issue #564 coalescing: a newer watched CHANGED during the retry delay
    /// supersedes the older pending retry. The first retry's deadline passes
    /// while the file is still invalid; it must not remove state because the
    /// second CHANGED owns convergence.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn watched_invalid_encoding_retry_is_superseded_by_newer_change() {
        let tmp = TempDir::new().unwrap();
        fs::create_dir(tmp.path().join("R")).unwrap();
        let helper_path = tmp.path().join("R").join("helper.R");
        let old_helper = "helper_fn <- function() 1\n";
        let recovered_helper = "helper_fn <- function() 2\n";
        fs::write(&helper_path, old_helper).unwrap();
        let parent = "source(\"R/helper.R\")\nhelper_fn()\n";
        fs::write(tmp.path().join("parent.R"), parent).unwrap();
        let (svc, parent_uri) =
            open_in_synthetic_package_workspace(&tmp, "parent.R", "r", parent).await;
        let backend = svc.inner();
        let helper_uri = Url::from_file_path(&helper_path).unwrap();
        seed_package_r_file_input(backend, tmp.path(), "R/helper.R", old_helper).await;

        std::fs::write(&helper_path, [0x78u8, 0x80, 0x79]).unwrap();
        let first_event_at = tokio::time::Instant::now();
        send_watched_change(backend, &helper_uri).await;

        let first_generation_seen = wait_for_state(backend, 1_000, |state| {
            state
                .watched_file_resync_generations
                .contains_key(&helper_uri)
        })
        .await;
        assert!(
            first_generation_seen,
            "first watched event must enter the generation table"
        );
        let first_generation = {
            let state = backend.state.read().await;
            *state
                .watched_file_resync_generations
                .get(&helper_uri)
                .expect("first generation remains current before second event")
        };

        let second_event_at = first_event_at + std::time::Duration::from_millis(300);
        if tokio::time::Instant::now() < second_event_at {
            tokio::time::sleep_until(second_event_at).await;
        }

        // A second watched event supersedes the first retry, but the file is
        // still invalid long enough that the first retry would remove state if
        // it were not generation-checked.
        send_watched_change(backend, &helper_uri).await;
        let second_generation_seen = wait_for_state(backend, 1_000, |state| {
            state
                .watched_file_resync_generations
                .get(&helper_uri)
                .is_some_and(|generation| *generation != first_generation)
        })
        .await;
        assert!(
            second_generation_seen,
            "second watched event must supersede the first generation"
        );
        let second_generation = {
            let state = backend.state.read().await;
            *state
                .watched_file_resync_generations
                .get(&helper_uri)
                .expect("second generation remains current before first retry deadline")
        };

        let after_first_retry_deadline = first_event_at
            + WATCHED_UNDECODABLE_RETRY_DELAY
            + std::time::Duration::from_millis(150);
        if tokio::time::Instant::now() < after_first_retry_deadline {
            tokio::time::sleep_until(after_first_retry_deadline).await;
        }
        {
            let state = backend.state.read().await;
            assert_eq!(
                state
                    .watched_file_resync_generations
                    .get(&helper_uri)
                    .copied(),
                Some(second_generation),
                "the second watched event's generation must still own the URI after the first retry deadline"
            );
            assert!(
                state
                    .cross_file_graph
                    .get_dependencies(&parent_uri)
                    .iter()
                    .any(|e| e.to == helper_uri),
                "the superseded first retry must not remove the parent edge"
            );
            assert!(
                state.package_inputs.r_files.contains_key(&helper_path),
                "the superseded first retry must not remove package input"
            );
        }

        fs::write(&helper_path, recovered_helper).unwrap();
        let recovered = wait_for_state(backend, 5_000, |state| {
            state.cross_file_file_cache.get(&helper_uri).as_deref() == Some(recovered_helper)
                && state
                    .cross_file_graph
                    .get_dependencies(&parent_uri)
                    .iter()
                    .any(|e| e.to == helper_uri)
        })
        .await;
        assert!(
            recovered,
            "the newer watched event's retry must commit recovered content"
        );
    }

    /// The missing-file branch has its own veto: a file deleted from disk
    /// whose URI is (re)opened must not have its cross-file state removed —
    /// the open buffer is authoritative even when no disk file backs it.
    #[tokio::test]
    async fn resync_missing_file_vetoes_when_reopened() {
        let tmp = TempDir::new().unwrap();
        let content = "source(\"extra.R\")\nx <- 1\n";
        fs::write(tmp.path().join("helper.R"), content).unwrap();
        fs::write(tmp.path().join("extra.R"), "extra_fn <- function() 2\n").unwrap();
        let (svc, helper_uri) = open_in_quiescent_workspace(&tmp, "helper.R", "r", content).await;
        let backend = svc.inner();
        let extra_uri = Url::from_file_path(tmp.path().join("extra.R")).unwrap();

        fs::remove_file(tmp.path().join("helper.R")).unwrap();

        // Call the missing-file branch directly (the resync entry point
        // would preflight-veto before ever reaching it) with the document
        // open, as a racing reopen would leave it.
        let outcome = resync_missing_file(
            &backend.state,
            &helper_uri,
            None,
            ResyncCommitMode::Immediate,
            RemovalDiskObservation::Missing,
        )
        .await;
        assert!(
            matches!(outcome, ResyncOutcome::Vetoed),
            "the missing-file branch must veto while the document is open"
        );
        let state = backend.state.read().await;
        assert!(
            state
                .cross_file_graph
                .get_dependencies(&helper_uri)
                .iter()
                .any(|e| e.to == extra_uri),
            "a vetoed removal must leave the open buffer's edges intact"
        );
    }

    /// Issue #558 test 3 (end-to-end half): close-then-immediate-reopen.
    /// Whatever order the spawned resync and the reopen's `did_open` land
    /// in, the reopened buffer's topology must win — either the resync
    /// commits first and `did_open` overwrites it, or `did_open` lands
    /// first and the resync's commit-time veto fires.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn close_then_reopen_keeps_reopened_buffer_topology() {
        let tmp = TempDir::new().unwrap();
        // Disk has NO source() edge; the reopened buffer adds one (unsaved).
        fs::write(tmp.path().join("helper.R"), "x <- 1\n").unwrap();
        fs::write(tmp.path().join("extra.R"), "extra_fn <- function() 2\n").unwrap();
        let (svc, helper_uri) =
            open_in_quiescent_workspace(&tmp, "helper.R", "r", "x <- 1\n").await;
        let backend = svc.inner();
        let extra_uri = Url::from_file_path(tmp.path().join("extra.R")).unwrap();

        let resync_handoff = backend
            .state
            .read()
            .await
            .close_resync_final_handoff_test_capture
            .arm_for(helper_uri.as_str());
        close_doc(backend, &helper_uri).await;
        // Immediate reopen with different (unsaved) buffer content.
        open_doc(
            backend,
            &helper_uri,
            "r",
            1,
            "source(\"extra.R\")\nx <- 1\n",
        )
        .await;

        let resync = wait_final_handoff_payload(
            backend,
            &resync_handoff,
            "close-resync-reopen",
            &[&helper_uri],
        )
        .await;
        assert!(
            resync.is_empty(),
            "a resync vetoed by the reopen must not select diagnostic consumers"
        );
        release_and_wait_final_handoff(
            backend,
            &resync_handoff,
            "close-resync-reopen",
            &[&helper_uri],
        )
        .await;
        let state = backend.state.read().await;
        assert!(
            state
                .cross_file_graph
                .get_dependencies(&helper_uri)
                .iter()
                .any(|e| e.to == extra_uri),
            "a stale disk commit must never clobber the reopened buffer's topology"
        );
    }

    #[tokio::test]
    async fn close_resync_empty_handoff_has_a_causal_completion() {
        let tmp = TempDir::new().unwrap();
        fs::write(tmp.path().join("standalone.R"), "value <- 1\n").unwrap();
        let (svc, uri) =
            open_in_quiescent_workspace(&tmp, "standalone.R", "r", "value <- 1\n").await;
        let backend = svc.inner();

        let (_, resync, completion) = close_with_final_handoff_capture(backend, &uri, true).await;
        assert!(
            resync.is_empty(),
            "a standalone close has no open diagnostic consumer"
        );
        let completion = completion.expect("the empty resync still owns a causal receipt");
        release_and_wait_final_handoff(backend, &completion, "close-resync", &[&uri]).await;
        assert!(!backend.state.read().await.documents.contains_key(&uri));
    }

    #[cfg(unix)]
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn close_resync_receipt_spans_every_alias_root() {
        let tmp = TempDir::new().unwrap();
        let real = tmp.path().join("real");
        fs::create_dir(&real).unwrap();
        std::os::unix::fs::symlink(&real, tmp.path().join("link")).unwrap();
        let content = "value <- 1\n";
        fs::write(real.join("shared.R"), content).unwrap();

        let svc = service_in_workspace_with_options(
            &tmp,
            Some(serde_json::json!({
                "crossFile": { "indexWorkspace": false },
                "packages": { "enabled": false }
            })),
        )
        .await;
        let backend = svc.inner();
        let alias_uri = Url::from_file_path(tmp.path().join("link/shared.R")).unwrap();
        let canonical_uri = Url::from_file_path(real.join("shared.R")).unwrap();
        open_doc_with_revalidation_handoff(backend, &alias_uri, "r", 1, content).await;

        let make_entry = |uri: &Url| {
            let tree = crate::parser_pool::with_parser(|parser| parser.parse(content, None));
            let metadata = Arc::new(crate::cross_file::extract_metadata(content));
            let artifacts = Arc::new(match tree.as_ref() {
                Some(tree) => crate::cross_file::scope::compute_artifacts_with_metadata(
                    uri,
                    tree,
                    content,
                    Some(&metadata),
                ),
                None => crate::cross_file::scope::ScopeArtifacts::default(),
            });
            crate::workspace_index::IndexEntry {
                contents: ropey::Rope::from_str(content),
                tree,
                loaded_packages: Vec::new(),
                data_packages: Vec::new(),
                snapshot: crate::cross_file::file_cache::FileSnapshot::with_content_hash(
                    &std::fs::metadata(uri.to_file_path().unwrap()).unwrap(),
                    content,
                ),
                metadata,
                artifacts,
                indexed_at_version: 0,
            }
        };
        let later_root = {
            let mut state = backend.state.write().await;
            state.workspace_scan_complete = true;
            state
                .workspace_index
                .insert(alias_uri.clone(), make_entry(&alias_uri));
            state
                .workspace_index
                .insert(canonical_uri.clone(), make_entry(&canonical_uri));
            let mut roots = [alias_uri.clone(), canonical_uri.clone()];
            roots.sort_unstable_by(|left, right| left.as_str().cmp(right.as_str()));
            roots[1].clone()
        };
        let later_pause = backend
            .state
            .read()
            .await
            .close_resync_post_attempt_test_pause
            .arm(later_root.clone());

        let (_, _, completion) = close_with_final_handoff_capture(backend, &alias_uri, true).await;
        let completion = completion.expect("multi-root close owns one aggregate resync receipt");
        completion.release();
        tokio::time::timeout(
            std::time::Duration::from_secs(5),
            later_pause.wait_arrived(),
        )
        .await
        .expect("the later authoritative root must enter its resync attempt");
        assert!(
            !completion.status().completed,
            "the aggregate receipt must remain open while a later root is paused"
        );
        assert!(
            completion
                .status()
                .outstanding
                .iter()
                .any(|(_, label)| *label == "close-resync-ticket"),
            "the later root must retain its pre-registered phase ticket"
        );
        later_pause.release();
        wait_final_handoff_completion(
            backend,
            &completion,
            "close-resync-multi-root",
            &[&alias_uri, &canonical_uri],
        )
        .await;
    }

    #[tokio::test]
    async fn close_resync_permits_are_shared_by_clones_not_services() {
        let (first, _) = tower_lsp::LspService::new(Backend::new);
        let (second, _) = tower_lsp::LspService::new(Backend::new);
        let first_backend = first.inner();
        let clone = first_backend.clone();
        assert!(Arc::ptr_eq(
            &first_backend.close_resync_permits,
            &clone.close_resync_permits
        ));
        assert!(!Arc::ptr_eq(
            &first_backend.close_resync_permits,
            &second.inner().close_resync_permits
        ));

        let _all_first_permits = first_backend
            .close_resync_permits
            .clone()
            .acquire_many_owned(CLOSE_RESYNC_CONCURRENCY as u32)
            .await
            .unwrap();
        let _independent_permit = tokio::time::timeout(
            std::time::Duration::from_millis(100),
            second.inner().close_resync_permits.acquire(),
        )
        .await
        .expect("one service's close burst must not block an independent service")
        .unwrap();
    }

    /// Issue #558 test 4: transitive dependents (grandparent -> parent ->
    /// helper) are revalidated and republished after the close resync
    /// restores disk content the unsaved buffer had removed.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn close_resync_revalidates_transitive_dependents() {
        let tmp = TempDir::new().unwrap();
        fs::write(tmp.path().join("helper.R"), "helper_fn <- function() 1\n").unwrap();
        fs::write(tmp.path().join("parent.R"), "source(\"helper.R\")\n").unwrap();
        fs::write(
            tmp.path().join("grandparent.R"),
            "source(\"parent.R\")\nhelper_fn()\n",
        )
        .unwrap();
        let svc = service_in_workspace_with_options(
            &tmp,
            Some(serde_json::json!({
                "crossFile": { "indexWorkspace": false },
                "packages": { "enabled": false }
            })),
        )
        .await;
        let backend = svc.inner();
        let grandparent_uri = Url::from_file_path(tmp.path().join("grandparent.R")).unwrap();
        let helper_uri = Url::from_file_path(tmp.path().join("helper.R")).unwrap();
        open_doc_with_revalidation_handoff(
            backend,
            &grandparent_uri,
            "r",
            1,
            "source(\"parent.R\")\nhelper_fn()\n",
        )
        .await;
        open_doc_with_revalidation_handoff(
            backend,
            &helper_uri,
            "r",
            1,
            "helper_fn <- function() 1\n",
        )
        .await;
        // The undefined-variable collector defers until the workspace scan
        // completes; the harness never runs `initialized`.
        backend.state.write().await.workspace_scan_complete = true;

        // Sanity: helper_fn resolves through the transitive chain.
        {
            let state = backend.state.read().await;
            assert!(
                snapshot_diagnostics(&state, &grandparent_uri).is_empty(),
                "helper_fn must resolve through parent -> helper before the edit"
            );
        }

        // Unsaved buffer edit deletes helper_fn; the grandparent now flags it.
        let change_handoff =
            change_doc_with_revalidation_handoff(backend, &helper_uri, 2, "x <- 1\n").await;
        assert!(
            change_handoff
                .iter()
                .any(|ticket| ticket.uri == grandparent_uri),
            "editing the helper must causally finish the grandparent revalidation"
        );
        {
            let state = backend.state.read().await;
            assert!(
                !snapshot_diagnostics(&state, &grandparent_uri).is_empty(),
                "deleting helper_fn in the buffer must flag the grandparent's call"
            );
        }
        let (transactional, resync, resync_handoff) =
            close_with_final_handoff_capture(backend, &helper_uri, true).await;
        let (close_publish_pause, force_before_publish, restored_before_publish) = {
            let state = backend.state.write().await;
            (
                state.diagnostics_test_pause.arm(grandparent_uri.clone()),
                state
                    .diagnostics_gate
                    .force_republish_count_for_test(&grandparent_uri),
                snapshot_diagnostics(&state, &grandparent_uri).is_empty(),
            )
        };
        let resync_handoff =
            resync_handoff.expect("the target close resync handoff must remain paused");
        resync_handoff.release();
        tokio::time::timeout(
            std::time::Duration::from_secs(5),
            close_publish_pause.wait_arrived(),
        )
        .await
        .expect("the close-resync diagnostics worker must reach its publish barrier");

        // The worker is parked post-compute, pre-commit: the resync must have
        // marked the transitive dependent, but cannot have consumed its marker.
        let (force_at_publish, restored_at_publish) = {
            let state = backend.state.read().await;
            (
                state
                    .diagnostics_gate
                    .force_republish_count_for_test(&grandparent_uri),
                snapshot_diagnostics(&state, &grandparent_uri).is_empty(),
            )
        };
        close_publish_pause.release();
        wait_final_handoff_completion(
            backend,
            &resync_handoff,
            "close-resync",
            &[&grandparent_uri],
        )
        .await;
        assert_eq!(
            transactional
                .iter()
                .filter(|ticket| ticket.uri == grandparent_uri)
                .count(),
            1,
            "the transactional close must own its pre-resync grandparent transition"
        );
        assert_eq!(
            transactional.len(),
            1,
            "the transactional close must not select a foreign consumer: {transactional:?}"
        );
        assert_eq!(
            resync
                .iter()
                .filter(|consumer| consumer.uri() == &grandparent_uri)
                .count(),
            1,
            "the disk resync must own the grandparent revalidation"
        );
        assert_eq!(
            resync.len(),
            1,
            "the disk resync must not select a foreign consumer: {resync:?}"
        );
        assert!(
            force_before_publish >= 1 && force_at_publish >= 1,
            "the close resync must force-mark the transitive dependent until publish"
        );
        assert!(
            restored_before_publish && restored_at_publish,
            "close resync must restore disk content before publishing the transitive dependent"
        );
        let state = backend.state.read().await;
        assert_eq!(
            state
                .diagnostics_gate
                .force_republish_count_for_test(&grandparent_uri),
            0,
            "the dependent's force-republish marker must be consumed by the publish tail"
        );
    }

    /// Issue #558 test 5: no transient empty-edge window. Between close and
    /// the disk commit, a dependent's diagnostics must never observe the
    /// closed file with its edges stripped — the buffer-derived edges stay
    /// in place until the resync atomically replaces them.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn close_resync_has_no_transient_empty_edge_window() {
        let tmp = TempDir::new().unwrap();
        fs::write(tmp.path().join("helper.R"), "helper_fn <- function() 1\n").unwrap();
        fs::write(
            tmp.path().join("parent.R"),
            "source(\"helper.R\")\nhelper_fn()\n",
        )
        .unwrap();
        let (svc, parent_uri) = open_in_quiescent_workspace(
            &tmp,
            "parent.R",
            "r",
            "source(\"helper.R\")\nhelper_fn()\n",
        )
        .await;
        let backend = svc.inner();
        let helper_uri = Url::from_file_path(tmp.path().join("helper.R")).unwrap();
        open_doc(backend, &helper_uri, "r", 1, "helper_fn <- function() 1\n").await;
        backend.state.write().await.workspace_scan_complete = true;
        {
            let state = backend.state.read().await;
            assert!(
                snapshot_diagnostics(&state, &parent_uri).is_empty(),
                "helper_fn must resolve before the close"
            );
        }

        close_doc(backend, &helper_uri).await;

        // Sample the dependent's diagnostics continuously through the resync
        // window: the parent -> helper edge and helper's resolvable content
        // must be visible at every instant (buffer == disk here, so the
        // final state is identical; only a transient strip could flag).
        let deadline = std::time::Instant::now() + std::time::Duration::from_millis(400);
        while std::time::Instant::now() < deadline {
            {
                let state = backend.state.read().await;
                assert!(
                    state
                        .cross_file_graph
                        .get_dependencies(&parent_uri)
                        .iter()
                        .any(|e| e.to == helper_uri),
                    "the parent -> helper edge must never transiently disappear"
                );
                assert!(
                    snapshot_diagnostics(&state, &parent_uri).is_empty(),
                    "the dependent must never transiently flag helper_fn during the resync"
                );
            }
            tokio::time::sleep(std::time::Duration::from_millis(5)).await;
        }
    }

    /// Closing a deleted-from-disk file removes its cross-file state
    /// entirely (graph edges in both directions, index entries) instead of
    /// leaving stale buffer-derived topology behind.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn close_of_deleted_file_removes_cross_file_state() {
        let tmp = TempDir::new().unwrap();
        let content = "source(\"extra.R\")\nx <- 1\n";
        fs::write(tmp.path().join("helper.R"), content).unwrap();
        fs::write(tmp.path().join("extra.R"), "extra_fn <- function() 2\n").unwrap();
        let (svc, helper_uri) = open_in_quiescent_workspace(&tmp, "helper.R", "r", content).await;
        let backend = svc.inner();
        let extra_uri = Url::from_file_path(tmp.path().join("extra.R")).unwrap();
        {
            let state = backend.state.read().await;
            assert!(
                state
                    .cross_file_graph
                    .get_dependencies(&helper_uri)
                    .iter()
                    .any(|e| e.to == extra_uri),
                "open buffer must contribute the helper -> extra edge"
            );
        }

        // Delete the underlying file while the buffer is still open, then close.
        fs::remove_file(tmp.path().join("helper.R")).unwrap();
        close_doc(backend, &helper_uri).await;

        let removed = wait_for_state(backend, 5_000, |state| {
            state
                .cross_file_graph
                .get_dependencies(&helper_uri)
                .is_empty()
                && state.workspace_index.get_metadata(&helper_uri).is_none()
        })
        .await;
        assert!(
            removed,
            "closing a deleted file must remove its graph edges and index entry"
        );
    }

    /// The close resync masks disk content with the closing document's
    /// editor-language classification, not the path: a file-backed document
    /// WITHOUT an Rmd/Quarto extension opened as `languageId: rmd` is
    /// chunk-masked while open, and the resync must not reclassify the same
    /// disk text as plain R (which would mint prose `source()` edges).
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn close_resync_respects_language_mode_chunk_classification() {
        let tmp = TempDir::new().unwrap();
        fs::write(tmp.path().join("helpers.R"), "helper_fn <- function() 1\n").unwrap();
        // Both decoy targets exist, so an unmasked (plain-R) parse of the
        // prose line would resolve a real edge.
        fs::write(tmp.path().join("prose_decoy.R"), "d <- 1\n").unwrap();
        // `.md` is not matched by the path classifier, so only the languageId
        // can classify this document as R Markdown.
        let content = concat!(
            "# Report\n",
            "\n",
            "source(\"prose_decoy.R\")\n",
            "\n",
            "```{r}\n",
            "source(\"helpers.R\")\n",
            "```\n",
        );
        fs::write(tmp.path().join("report.md"), content).unwrap();
        let (svc, report_uri) =
            open_in_quiescent_workspace(&tmp, "report.md", "rmd", content).await;
        let backend = svc.inner();
        let helpers_uri = Url::from_file_path(tmp.path().join("helpers.R")).unwrap();
        let decoy_uri = Url::from_file_path(tmp.path().join("prose_decoy.R")).unwrap();

        // Sanity: while open (languageId-classified, masked), only the chunk
        // edge exists.
        {
            let state = backend.state.read().await;
            let deps = state.cross_file_graph.get_dependencies(&report_uri);
            assert!(
                deps.iter().any(|e| e.to == helpers_uri),
                "chunk source() must produce an edge while open"
            );
            assert!(
                !deps.iter().any(|e| e.to == decoy_uri),
                "prose source() must not produce an edge while open"
            );
        }

        close_doc(backend, &report_uri).await;

        // The resync installs disk-derived index metadata; wait for it, then
        // assert the classification survived the close.
        let resynced = wait_for_state(backend, 5_000, |state| {
            state.workspace_index.get_metadata(&report_uri).is_some()
        })
        .await;
        assert!(resynced, "close resync must install index metadata");
        let state = backend.state.read().await;
        let deps = state.cross_file_graph.get_dependencies(&report_uri);
        assert!(
            deps.iter().any(|e| e.to == helpers_uri),
            "the chunk edge must survive the close resync"
        );
        assert!(
            !deps.iter().any(|e| e.to == decoy_uri),
            "the resync must keep the editor-language chunk masking — prose must never become an edge"
        );
    }

    /// Issue #563: a watched CHANGED after closing an extension-mismatched Rmd
    /// keeps using the persisted editor-language chunk kind. Without the
    /// override, the watched path passes `chunk_kind: None`, reclassifies this
    /// `.md` as plain R, and prose `source()` / `# raven: source` entries become
    /// graph edges.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn issue563_watched_change_after_closing_extension_mismatched_rmd_preserves_masking() {
        let tmp = TempDir::new().unwrap();
        fs::write(tmp.path().join("helpers.R"), "helper_fn <- function() 1\n").unwrap();
        fs::write(tmp.path().join("extra.R"), "extra_fn <- function() 2\n").unwrap();
        fs::write(tmp.path().join("prose_call.R"), "call_decoy <- 1\n").unwrap();
        fs::write(
            tmp.path().join("prose_directive.R"),
            "directive_decoy <- 1\n",
        )
        .unwrap();
        let report_v1 = concat!(
            "# Report\n",
            "\n",
            "# raven: source prose_directive.R\n",
            "source(\"prose_call.R\")\n",
            "\n",
            "```{r}\n",
            "source(\"helpers.R\")\n",
            "```\n",
        );
        fs::write(tmp.path().join("report.md"), report_v1).unwrap();
        let (svc, report_uri) =
            open_in_quiescent_workspace(&tmp, "report.md", "rmd", report_v1).await;
        let backend = svc.inner();
        let helpers_uri = Url::from_file_path(tmp.path().join("helpers.R")).unwrap();
        let extra_uri = Url::from_file_path(tmp.path().join("extra.R")).unwrap();
        let prose_call_uri = Url::from_file_path(tmp.path().join("prose_call.R")).unwrap();
        let prose_directive_uri =
            Url::from_file_path(tmp.path().join("prose_directive.R")).unwrap();

        close_doc(backend, &report_uri).await;
        let closed_resync_installed = wait_for_state(backend, 5_000, |state| {
            state.editor_chunk_kind_overrides.get(&report_uri).copied()
                == Some(crate::chunks::ChunkKind::Rmd)
                && state.workspace_index.get_metadata(&report_uri).is_some()
                && state
                    .cross_file_graph
                    .get_dependencies(&report_uri)
                    .iter()
                    .any(|e| e.to == helpers_uri)
        })
        .await;
        assert!(
            closed_resync_installed,
            "close must persist the editor chunk kind and install disk-derived state"
        );

        let report_v2 = concat!(
            "# Report\n",
            "\n",
            "# raven: source prose_directive.R\n",
            "source(\"prose_call.R\")\n",
            "\n",
            "```{r}\n",
            "source(\"extra.R\")\n",
            "```\n",
        );
        fs::write(tmp.path().join("report.md"), report_v2).unwrap();
        send_watched_change(backend, &report_uri).await;

        let updated = wait_for_state(backend, 5_000, |state| {
            let deps = state.cross_file_graph.get_dependencies(&report_uri);
            deps.iter().any(|e| e.to == extra_uri) && !deps.iter().any(|e| e.to == helpers_uri)
        })
        .await;
        assert!(
            updated,
            "watched CHANGED must update the chunk edge for the closed mismatched Rmd"
        );

        let state = backend.state.read().await;
        let deps = state.cross_file_graph.get_dependencies(&report_uri);
        assert!(
            !deps.iter().any(|e| e.to == prose_call_uri),
            "prose source() must remain masked after watched resync"
        );
        assert!(
            !deps.iter().any(|e| e.to == prose_directive_uri),
            "prose # raven: source must remain masked after watched resync"
        );
    }

    /// Issue #563: after the index entries for a closed extension-mismatched
    /// Rmd are evicted, `get_enriched_metadata` falls back to the raw file
    /// cache. That fallback must consult the persisted editor-language chunk
    /// kind before path classification.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn issue563_get_enriched_metadata_file_cache_fallback_uses_persisted_chunk_kind() {
        let tmp = TempDir::new().unwrap();
        fs::write(tmp.path().join("helpers.R"), "helper_fn <- function() 1\n").unwrap();
        fs::write(tmp.path().join("prose_call.R"), "call_decoy <- 1\n").unwrap();
        fs::write(
            tmp.path().join("prose_directive.R"),
            "directive_decoy <- 1\n",
        )
        .unwrap();
        let report = concat!(
            "# Report\n",
            "\n",
            "# raven: source prose_directive.R\n",
            "source(\"prose_call.R\")\n",
            "\n",
            "```{r}\n",
            "source(\"helpers.R\")\n",
            "```\n",
        );
        fs::write(tmp.path().join("report.md"), report).unwrap();
        let (svc, report_uri) = open_in_quiescent_workspace(&tmp, "report.md", "rmd", report).await;
        let backend = svc.inner();

        close_doc(backend, &report_uri).await;
        let cached = wait_for_state(backend, 5_000, |state| {
            state.cross_file_file_cache.get(&report_uri).as_deref() == Some(report)
                && state.editor_chunk_kind_overrides.get(&report_uri).copied()
                    == Some(crate::chunks::ChunkKind::Rmd)
        })
        .await;
        assert!(
            cached,
            "close resync must leave raw file-cache content and a chunk-kind override"
        );

        {
            let state = backend.state.write().await;
            state.workspace_index.invalidate(&report_uri);
            state.workspace_index.invalidate(&report_uri);
        }

        let state = backend.state.read().await;
        let meta = state
            .get_enriched_metadata(&report_uri)
            .expect("file-cache fallback metadata must be available");
        let source_paths: Vec<&str> = meta.sources.iter().map(|s| s.path.as_str()).collect();
        assert_eq!(
            source_paths,
            vec!["helpers.R"],
            "file-cache fallback must extract metadata from chunks only"
        );
    }

    /// `.Rmarkdown` is a knitr-supported R Markdown extension and should be
    /// path-classified as Rmd even with no editor language signal. A direct disk
    /// resync is enough to prove the closed-file path masks prose before
    /// extracting graph edges.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn issue563_rmarkdown_extension_path_classified_resync_masks_prose_without_editor_signal()
    {
        let tmp = TempDir::new().unwrap();
        fs::write(tmp.path().join("main.R"), "x <- 1\n").unwrap();
        fs::write(tmp.path().join("helpers.R"), "helper_fn <- function() 1\n").unwrap();
        fs::write(tmp.path().join("prose_call.R"), "call_decoy <- 1\n").unwrap();
        let report = concat!(
            "# Report\n",
            "\n",
            "source(\"prose_call.R\")\n",
            "\n",
            "```{r}\n",
            "source(\"helpers.R\")\n",
            "```\n",
        );
        fs::write(tmp.path().join("report.Rmarkdown"), report).unwrap();
        let (svc, _main_uri) = open_in_quiescent_workspace(&tmp, "main.R", "r", "x <- 1\n").await;
        let backend = svc.inner();
        let report_uri = Url::from_file_path(tmp.path().join("report.Rmarkdown")).unwrap();
        let helpers_uri = Url::from_file_path(tmp.path().join("helpers.R")).unwrap();
        let prose_call_uri = Url::from_file_path(tmp.path().join("prose_call.R")).unwrap();

        let outcome = resync_file_from_disk(
            &backend.state,
            &report_uri,
            None,
            None,
            true,
            None,
            ResyncCommitMode::Immediate,
        )
        .await;
        assert!(
            matches!(outcome, ResyncOutcome::Updated { .. }),
            ".Rmarkdown disk resync must commit without an editor language signal"
        );

        let state = backend.state.read().await;
        assert!(
            !state.editor_chunk_kind_overrides.contains_key(&report_uri),
            "path-classified .Rmarkdown files do not need an editor override"
        );
        let deps = state.cross_file_graph.get_dependencies(&report_uri);
        assert!(
            deps.iter().any(|e| e.to == helpers_uri),
            "chunk source() must produce an edge for path-classified .Rmarkdown"
        );
        assert!(
            !deps.iter().any(|e| e.to == prose_call_uri),
            "prose source() must be masked for path-classified .Rmarkdown"
        );
    }

    /// Issue #563: removing a file's closed cross-file state also drops the
    /// persisted editor-language chunk-kind override. Recreating the same path
    /// later should not inherit an old language classification until the editor
    /// opens it again.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn issue563_deleting_extension_mismatched_rmd_prunes_persisted_chunk_kind() {
        use tower_lsp::lsp_types::{DidChangeWatchedFilesParams, FileChangeType, FileEvent};

        let tmp = TempDir::new().unwrap();
        fs::write(tmp.path().join("helpers.R"), "helper_fn <- function() 1\n").unwrap();
        let report = concat!(
            "# Report\n",
            "\n",
            "```{r}\n",
            "source(\"helpers.R\")\n",
            "```\n",
        );
        fs::write(tmp.path().join("report.md"), report).unwrap();
        let (svc, report_uri) = open_in_quiescent_workspace(&tmp, "report.md", "rmd", report).await;
        let backend = svc.inner();

        close_doc(backend, &report_uri).await;
        let persisted = wait_for_state(backend, 5_000, |state| {
            state.editor_chunk_kind_overrides.get(&report_uri).copied()
                == Some(crate::chunks::ChunkKind::Rmd)
                && state.workspace_index.get_metadata(&report_uri).is_some()
        })
        .await;
        assert!(
            persisted,
            "close must persist the editor-derived chunk kind before deletion"
        );

        fs::remove_file(tmp.path().join("report.md")).unwrap();
        backend
            .did_change_watched_files(DidChangeWatchedFilesParams {
                changes: vec![FileEvent {
                    uri: report_uri.clone(),
                    typ: FileChangeType::DELETED,
                }],
            })
            .await;

        let state = backend.state.read().await;
        assert!(
            !state.editor_chunk_kind_overrides.contains_key(&report_uri),
            "deletion convergence must prune the persisted chunk kind"
        );
        assert!(
            state
                .cross_file_graph
                .get_dependencies(&report_uri)
                .is_empty(),
            "deletion convergence must remove graph state too"
        );
        assert!(
            state.workspace_index.get_metadata(&report_uri).is_none(),
            "deletion convergence must remove workspace-index metadata"
        );
    }

    /// An open file that is BOTH a package-visibility sibling and a graph
    /// dependent of the closing document must appear once in the
    /// transactional close fanout, alongside a package-only sibling. The
    /// later disk resync is a distinct real transition: it selects the graph
    /// dependent once, but must not reselect the package-only sibling.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn close_marks_overlapping_package_sibling_and_dependent_once() {
        let tmp = TempDir::new().unwrap();
        fs::create_dir(tmp.path().join("R")).unwrap();
        fs::write(tmp.path().join("R").join("a.R"), "a_fn <- function() 1\n").unwrap();
        let b_disk = "source(\"a.R\")\nb_fn <- function() 2\n";
        fs::write(tmp.path().join("R").join("b.R"), b_disk).unwrap();
        // Package-only sibling: open R/ file with NO edge to a.R.
        let c_disk = "c_fn <- function() 3\n";
        fs::write(tmp.path().join("R").join("c.R"), c_disk).unwrap();
        let (svc, b_uri) = open_in_synthetic_package_workspace(&tmp, "R/b.R", "r", b_disk).await;
        let backend = svc.inner();
        let a_uri = Url::from_file_path(tmp.path().join("R").join("a.R")).unwrap();
        let c_uri = Url::from_file_path(tmp.path().join("R").join("c.R")).unwrap();
        open_doc(backend, &a_uri, "r", 1, "a_fn <- function() 1\n").await;
        open_doc(backend, &c_uri, "r", 1, c_disk).await;

        // Activate REAL package mode (a bare workspace_root without a
        // DESCRIPTION never derives a scope contribution, so
        // pkg_visibility_changed would stay false and the sibling fanout
        // would be empty), then make a's close change package visibility
        // (buffer-only symbol discarded on close).
        {
            let mut state = backend.state.write().await;
            state.package_inputs.workspace_root = Some(tmp.path().to_path_buf());
            state.package_inputs.description = Some(crate::package_state::DescriptionInput {
                text: "Package: testpkg\nVersion: 1.0\n".into(),
            });
            state.apply_package_event(&crate::package_state::PackageInputDelta::Initial);
        }
        change_doc(
            backend,
            &a_uri,
            2,
            "a_fn <- function() 1\nbuffer_only_fn <- function() 2\n",
        )
        .await;
        // Drain the open/change fanout so the assertions below observe only
        // the close's marking.
        let drained = wait_for_state(backend, 5_000, |state| {
            state
                .diagnostics_gate
                .force_republish_count_for_test(&b_uri)
                == 0
                && state
                    .diagnostics_gate
                    .force_republish_count_for_test(&c_uri)
                    == 0
        })
        .await;
        assert!(
            drained,
            "the open/change fanout must drain before the close"
        );

        let (transactional, resync, resync_handoff) =
            close_with_final_handoff_capture(backend, &a_uri, true).await;
        assert_eq!(
            transactional
                .iter()
                .filter(|ticket| ticket.uri == b_uri)
                .count(),
            1,
            "the transactional package fanout must deduplicate the overlapping sibling/dependent"
        );
        assert_eq!(
            transactional
                .iter()
                .filter(|ticket| ticket.uri == c_uri)
                .count(),
            1,
            "the package-only sibling must have one transactional consumer"
        );
        assert_eq!(
            resync
                .iter()
                .filter(|consumer| consumer.uri() == &b_uri)
                .count(),
            1,
            "the disk resync must select its graph dependent exactly once"
        );
        assert_eq!(
            resync.len(),
            1,
            "the disk resync must not reselect the package-only sibling or any foreign consumer: \
             transactional={transactional:?}, resync={resync:?}"
        );
        let resync_handoff = resync_handoff.unwrap();
        release_and_wait_final_handoff(backend, &resync_handoff, "close-resync", &[&b_uri, &c_uri])
            .await;
    }

    /// Exists -> missing -> exists: deleting a sourced file strips the open
    /// parent's edge (removal is total), and recreating the file must
    /// restore it — the recreated child's own metadata cannot re-derive an
    /// edge owned by PARENT metadata, so the resync re-runs the open
    /// parents' graph updates.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn recreated_file_restores_open_parent_edges() {
        use tower_lsp::lsp_types::{DidChangeWatchedFilesParams, FileChangeType, FileEvent};

        let tmp = TempDir::new().unwrap();
        fs::write(tmp.path().join("child.R"), "child_fn <- function() 1\n").unwrap();
        let parent = "source(\"child.R\")\nchild_fn()\n";
        fs::write(tmp.path().join("parent.R"), parent).unwrap();
        let (svc, parent_uri) = open_in_quiescent_workspace(&tmp, "parent.R", "r", parent).await;
        let backend = svc.inner();
        let child_uri = Url::from_file_path(tmp.path().join("child.R")).unwrap();
        {
            let state = backend.state.read().await;
            assert!(
                state
                    .cross_file_graph
                    .get_dependencies(&parent_uri)
                    .iter()
                    .any(|e| e.to == child_uri),
                "precondition: the parent -> child edge exists"
            );
        }

        // Delete: the DELETED branch removes ALL of child's edges, including
        // the parent-owned one.
        fs::remove_file(tmp.path().join("child.R")).unwrap();
        backend
            .did_change_watched_files(DidChangeWatchedFilesParams {
                changes: vec![FileEvent {
                    uri: child_uri.clone(),
                    typ: FileChangeType::DELETED,
                }],
            })
            .await;
        {
            let state = backend.state.read().await;
            assert!(
                !state
                    .cross_file_graph
                    .get_dependencies(&parent_uri)
                    .iter()
                    .any(|e| e.to == child_uri),
                "deletion must strip the parent -> child edge"
            );
        }

        // Recreate: the resync must restore the open parent's edge.
        fs::write(tmp.path().join("child.R"), "child_fn <- function() 1\n").unwrap();
        backend
            .did_change_watched_files(DidChangeWatchedFilesParams {
                changes: vec![FileEvent {
                    uri: child_uri.clone(),
                    typ: FileChangeType::CREATED,
                }],
            })
            .await;
        let restored = wait_for_state(backend, 5_000, |state| {
            state
                .cross_file_graph
                .get_dependencies(&parent_uri)
                .iter()
                .any(|e| e.to == child_uri)
        })
        .await;
        assert!(
            restored,
            "recreating the file must restore the open parent's source() edge"
        );
    }

    /// Closing an unchanged buffer resyncs its disk state into the single
    /// closed-document authority.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn close_resync_installs_disk_content_in_closed_index() {
        use tower_lsp::lsp_types::{DidCloseTextDocumentParams, TextDocumentIdentifier};

        let tmp = TempDir::new().unwrap();
        fs::write(tmp.path().join("helper.R"), "helper_fn <- function() 1\n").unwrap();
        let (svc, helper_uri) =
            open_in_quiescent_workspace(&tmp, "helper.R", "r", "helper_fn <- function() 1\n").await;
        let backend = svc.inner();

        backend
            .did_close(DidCloseTextDocumentParams {
                text_document: TextDocumentIdentifier {
                    uri: helper_uri.clone(),
                },
            })
            .await;

        let installed = wait_for_state(backend, 5_000, |state| {
            state
                .workspace_index
                .get(&helper_uri)
                .is_some_and(|entry| entry.contents == "helper_fn <- function() 1\n")
        })
        .await;
        assert!(
            installed,
            "the resync commit must install current disk content in the closed index"
        );
    }

    /// A file whose disk content became undecodable converges like a missing
    /// file on close: the package input side already removes it
    /// (`on_disk_text: None`), and the cross-file side must not strand the
    /// discarded buffer's graph entry.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn close_of_undecodable_file_removes_cross_file_state() {
        use tower_lsp::lsp_types::{DidCloseTextDocumentParams, TextDocumentIdentifier};

        let tmp = TempDir::new().unwrap();
        let content = "source(\"extra.R\")\nx <- 1\n";
        fs::write(tmp.path().join("helper.R"), content).unwrap();
        fs::write(tmp.path().join("extra.R"), "extra_fn <- function() 2\n").unwrap();
        let (svc, helper_uri) = open_in_quiescent_workspace(&tmp, "helper.R", "r", content).await;
        let backend = svc.inner();
        {
            let state = backend.state.read().await;
            assert!(
                !state
                    .cross_file_graph
                    .get_dependencies(&helper_uri)
                    .is_empty(),
                "precondition: the buffer's edge exists"
            );
        }

        // Replace the disk content with invalid UTF-8 (no BOM: a lone
        // continuation byte), then close.
        std::fs::write(tmp.path().join("helper.R"), [0x78u8, 0x80, 0x79]).unwrap();
        backend
            .did_close(DidCloseTextDocumentParams {
                text_document: TextDocumentIdentifier {
                    uri: helper_uri.clone(),
                },
            })
            .await;

        let removed = wait_for_state(backend, 5_000, |state| {
            state
                .cross_file_graph
                .get_dependencies(&helper_uri)
                .is_empty()
                && state.workspace_index.get_metadata(&helper_uri).is_none()
        })
        .await;
        assert!(
            removed,
            "undecodable disk content must converge like a missing file"
        );
    }

    /// Watched CHANGED/DELETED events for CLOSED `.Rmd` documents flow
    /// through the resync (the old skip guard pre-dated masked resyncs):
    /// external edits update the chunk-derived edges, and deletion removes
    /// the state the close resync installed.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn watched_events_update_and_remove_closed_rmd_state() {
        use tower_lsp::lsp_types::{
            DidChangeWatchedFilesParams, DidCloseTextDocumentParams, FileChangeType, FileEvent,
            TextDocumentIdentifier,
        };

        let tmp = TempDir::new().unwrap();
        fs::write(tmp.path().join("helpers.R"), "helper_fn <- function() 1\n").unwrap();
        fs::write(tmp.path().join("extra.R"), "extra_fn <- function() 2\n").unwrap();
        fs::write(tmp.path().join("prose_decoy.R"), "d <- 1\n").unwrap();
        let rmd_v1 = concat!(
            "# Report\n",
            "\n",
            "source(\"prose_decoy.R\")\n",
            "\n",
            "```{r}\n",
            "source(\"helpers.R\")\n",
            "```\n",
        );
        fs::write(tmp.path().join("analysis.Rmd"), rmd_v1).unwrap();
        let (svc, rmd_uri) = open_in_quiescent_workspace(&tmp, "analysis.Rmd", "rmd", rmd_v1).await;
        let backend = svc.inner();
        let helpers_uri = Url::from_file_path(tmp.path().join("helpers.R")).unwrap();
        let extra_uri = Url::from_file_path(tmp.path().join("extra.R")).unwrap();
        let decoy_uri = Url::from_file_path(tmp.path().join("prose_decoy.R")).unwrap();

        // Close (installs disk-derived state), then edit the CLOSED file on
        // disk, re-pointing the chunk edge.
        backend
            .did_close(DidCloseTextDocumentParams {
                text_document: TextDocumentIdentifier {
                    uri: rmd_uri.clone(),
                },
            })
            .await;
        let installed = wait_for_state(backend, 5_000, |state| {
            state
                .cross_file_graph
                .get_dependencies(&rmd_uri)
                .iter()
                .any(|e| e.to == helpers_uri)
        })
        .await;
        assert!(installed, "close resync must install the chunk edge");

        let rmd_v2 = concat!(
            "# Report\n",
            "\n",
            "source(\"prose_decoy.R\")\n",
            "\n",
            "```{r}\n",
            "source(\"extra.R\")\n",
            "```\n",
        );
        fs::write(tmp.path().join("analysis.Rmd"), rmd_v2).unwrap();
        backend
            .did_change_watched_files(DidChangeWatchedFilesParams {
                changes: vec![FileEvent {
                    uri: rmd_uri.clone(),
                    typ: FileChangeType::CHANGED,
                }],
            })
            .await;
        let updated = wait_for_state(backend, 5_000, |state| {
            let deps = state.cross_file_graph.get_dependencies(&rmd_uri);
            deps.iter().any(|e| e.to == extra_uri) && !deps.iter().any(|e| e.to == helpers_uri)
        })
        .await;
        assert!(
            updated,
            "a watched CHANGED for a closed Rmd must update its chunk edge"
        );
        {
            let state = backend.state.read().await;
            assert!(
                !state
                    .cross_file_graph
                    .get_dependencies(&rmd_uri)
                    .iter()
                    .any(|e| e.to == decoy_uri),
                "prose source() must stay masked through the watched resync"
            );
        }

        // Delete the closed Rmd: its installed state must be removed.
        fs::remove_file(tmp.path().join("analysis.Rmd")).unwrap();
        backend
            .did_change_watched_files(DidChangeWatchedFilesParams {
                changes: vec![FileEvent {
                    uri: rmd_uri.clone(),
                    typ: FileChangeType::DELETED,
                }],
            })
            .await;
        let state = backend.state.read().await;
        assert!(
            state.cross_file_graph.get_dependencies(&rmd_uri).is_empty(),
            "deleting a closed Rmd must remove its graph state"
        );
        assert!(
            state.workspace_index.get_metadata(&rmd_uri).is_none(),
            "deleting a closed Rmd must remove its index entry"
        );
    }

    /// A close-time package-visibility change must reach `load_all()`
    /// carriers (root-level scripts that are not `is_r_source_path`), the
    /// same widening every watcher-driven visibility fanout applies.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn close_visibility_fanout_reaches_load_all_carriers() {
        let tmp = TempDir::new().unwrap();
        fs::create_dir(tmp.path().join("R")).unwrap();
        fs::write(tmp.path().join("R").join("a.R"), "a_fn <- function() 1\n").unwrap();
        let analysis = "devtools::load_all()\na_fn()\n";
        fs::write(tmp.path().join("analysis.R"), analysis).unwrap();
        let (svc, analysis_uri) =
            open_in_synthetic_package_workspace(&tmp, "analysis.R", "r", analysis).await;
        let backend = svc.inner();
        let a_uri = Url::from_file_path(tmp.path().join("R").join("a.R")).unwrap();
        open_doc(backend, &a_uri, "r", 1, "a_fn <- function() 1\n").await;

        {
            let mut state = backend.state.write().await;
            state.package_inputs.workspace_root = Some(tmp.path().to_path_buf());
            state.package_inputs.description = Some(crate::package_state::DescriptionInput {
                text: "Package: testpkg\nVersion: 1.0\n".into(),
            });
            state.apply_package_event(&crate::package_state::PackageInputDelta::Initial);
        }
        change_doc(
            backend,
            &a_uri,
            2,
            "a_fn <- function() 1\nbuffer_only_fn <- function() 2\n",
        )
        .await;
        let drained = wait_for_state(backend, 5_000, |state| {
            state
                .diagnostics_gate
                .force_republish_count_for_test(&analysis_uri)
                == 0
        })
        .await;
        assert!(drained, "pre-close fanout must drain");

        let (transactional, _, _) = close_with_final_handoff_capture(backend, &a_uri, false).await;
        assert_eq!(
            transactional
                .iter()
                .map(|ticket| &ticket.uri)
                .collect::<Vec<_>>(),
            vec![&analysis_uri],
            "only the load_all widening can select the non-source carrier"
        );
    }

    /// Closing a dirty package source reverts its package input to DISK
    /// truth: symbols that existed only in the discarded buffer must leave
    /// `package_inputs.r_files` (previously the close event installed the
    /// buffer text, stranding buffer-only symbols until a watcher event that
    /// never comes — disk was never touched).
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn close_reverts_package_input_to_disk_text() {
        let tmp = TempDir::new().unwrap();
        fs::create_dir(tmp.path().join("R")).unwrap();
        let disk = "pkg_fn <- function() 1\n";
        fs::write(tmp.path().join("R").join("helper.R"), disk).unwrap();
        let (svc, helper_uri) =
            open_in_synthetic_package_workspace(&tmp, "R/helper.R", "r", disk).await;
        let backend = svc.inner();
        let helper_path = tmp.path().join("R").join("helper.R");

        // Activate package mode after open; the did_change below then routes
        // through the package event pipeline.
        backend.state.write().await.package_inputs.workspace_root = Some(tmp.path().to_path_buf());

        change_doc(
            backend,
            &helper_uri,
            2,
            "pkg_fn <- function() 1\nbuffer_only_fn <- function() 2\n",
        )
        .await;
        {
            let state = backend.state.read().await;
            let input = state
                .package_inputs
                .r_files
                .get(&helper_path)
                .expect("did_change must install the buffer text as a package input");
            assert!(
                input.text.contains("buffer_only_fn"),
                "precondition: the live buffer text carries the buffer-only symbol"
            );
        }

        close_doc(backend, &helper_uri).await;

        // The DidClose translate runs synchronously inside did_close's write
        // lock, so the post-close state is final.
        let state = backend.state.read().await;
        let input = state
            .package_inputs
            .r_files
            .get(&helper_path)
            .expect("the file still exists on disk, so its input must remain");
        assert_eq!(
            input.text.as_ref(),
            disk,
            "close must revert the package input to exactly the disk text"
        );
    }

    /// Closing a package source whose disk file was deleted while the buffer
    /// was open removes it from `package_inputs.r_files` — the watcher's
    /// DELETED event was skipped ("open docs are authoritative"), so the
    /// close is the last chance to converge.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn close_of_deleted_package_source_removes_package_input() {
        let tmp = TempDir::new().unwrap();
        fs::create_dir(tmp.path().join("R")).unwrap();
        let disk = "pkg_fn <- function() 1\n";
        fs::write(tmp.path().join("R").join("helper.R"), disk).unwrap();
        let (svc, helper_uri) =
            open_in_synthetic_package_workspace(&tmp, "R/helper.R", "r", disk).await;
        let backend = svc.inner();
        let helper_path = tmp.path().join("R").join("helper.R");

        backend.state.write().await.package_inputs.workspace_root = Some(tmp.path().to_path_buf());
        // Seed the input through the live pipeline (buffer text).
        change_doc(backend, &helper_uri, 2, "pkg_fn <- function() 1\nx <- 1\n").await;
        assert!(
            backend
                .state
                .read()
                .await
                .package_inputs
                .r_files
                .contains_key(&helper_path),
            "precondition: the open buffer's input is tracked"
        );

        fs::remove_file(&helper_path).unwrap();
        close_doc(backend, &helper_uri).await;

        let state = backend.state.read().await;
        assert!(
            !state.package_inputs.r_files.contains_key(&helper_path),
            "closing a disk-deleted package source must drop its package input"
        );
    }

    /// Closing a project-excluded package source must converge package inputs to
    /// "not present", even if the file still exists on disk. Otherwise an
    /// excluded `R/generated.R` re-enters package mode as soon as its buffer is
    /// closed.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn close_of_project_excluded_package_source_removes_package_input() {
        let tmp = TempDir::new().unwrap();
        fs::create_dir(tmp.path().join("R")).unwrap();
        fs::write(
            tmp.path().join("raven.toml"),
            "[workspace]\nexclude = [\"R/generated.R\"]\n",
        )
        .unwrap();
        fs::write(
            tmp.path().join("DESCRIPTION"),
            "Package: testpkg\nVersion: 1.0\n",
        )
        .unwrap();
        let disk = "excluded_fn <- function() 1\n";
        fs::write(tmp.path().join("R").join("generated.R"), disk).unwrap();
        let (svc, generated_uri) =
            open_in_synthetic_package_workspace(&tmp, "R/generated.R", "r", disk).await;
        let backend = svc.inner();
        let generated_path = tmp.path().join("R").join("generated.R");

        {
            let mut state = backend.state.write().await;
            assert!(state.workspace_exclusions.is_excluded_uri(&generated_uri));
            state.package_inputs.workspace_root = Some(tmp.path().to_path_buf());
            state.package_inputs.description = Some(crate::package_state::DescriptionInput {
                text: "Package: testpkg\nVersion: 1.0\n".into(),
            });
        }

        close_doc(backend, &generated_uri).await;

        let state = backend.state.read().await;
        assert!(
            !state.package_inputs.r_files.contains_key(&generated_path),
            "excluded package source must not be restored from disk on close"
        );
        assert!(
            !state
                .package_state
                .scope_contribution()
                .r_internal_symbols
                .contains("excluded_fn"),
            "symbols from an excluded package source must not persist after close"
        );
    }

    /// A stale `workspace_index` entry (planted by the startup scan or
    /// on-demand indexing) outranks `workspace_index` in
    /// `get_enriched_metadata` and the content provider, so the resync's
    /// commit must invalidate it — otherwise the freshly committed disk
    /// state is shadowed and dependents keep resolving the pre-resync
    /// interface.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn close_resync_overrides_stale_unified_index_entry() {
        let tmp = TempDir::new().unwrap();
        fs::write(tmp.path().join("helper.R"), "helper_fn <- function() 1\n").unwrap();
        fs::write(
            tmp.path().join("parent.R"),
            "source(\"helper.R\")\nhelper_fn()\n",
        )
        .unwrap();
        let svc = service_in_workspace_with_options(
            &tmp,
            Some(serde_json::json!({
                "crossFile": { "indexWorkspace": false },
                "packages": { "enabled": false }
            })),
        )
        .await;
        let backend = svc.inner();
        let parent_uri = Url::from_file_path(tmp.path().join("parent.R")).unwrap();
        let helper_uri = Url::from_file_path(tmp.path().join("helper.R")).unwrap();
        open_doc_with_revalidation_handoff(
            backend,
            &parent_uri,
            "r",
            1,
            "source(\"helper.R\")\nhelper_fn()\n",
        )
        .await;
        {
            let mut state = backend.state.write().await;
            state.workspace_scan_complete = true;
        }

        // Plant a STALE unified-index entry for helper.R, simulating a scan
        // snapshot taken before the file's current disk content (it defines
        // old_fn, not helper_fn).
        {
            let stale = "old_fn <- function() 1\n";
            let tree = crate::parser_pool::with_parser(|p| p.parse(stale, None));
            let metadata = std::sync::Arc::new(crate::cross_file::extract_metadata(stale));
            let artifacts = std::sync::Arc::new(match tree.as_ref() {
                Some(t) => crate::cross_file::scope::compute_artifacts_with_metadata(
                    &helper_uri,
                    t,
                    stale,
                    Some(&metadata),
                ),
                None => crate::cross_file::scope::ScopeArtifacts::default(),
            });
            let fs_meta = std::fs::metadata(tmp.path().join("helper.R")).unwrap();
            let entry = crate::workspace_index::IndexEntry {
                contents: ropey::Rope::from_str(stale),
                tree,
                loaded_packages: Vec::new(),
                data_packages: vec![],
                snapshot: crate::cross_file::file_cache::FileSnapshot::with_content_hash(
                    &fs_meta, stale,
                ),
                metadata,
                artifacts,
                indexed_at_version: 0,
            };
            let state = backend.state.read().await;
            state.workspace_index.insert(helper_uri.clone(), entry);
        }
        // Precondition: the stale entry shadows every lower tier, so the
        // parent cannot resolve helper_fn.
        {
            let state = backend.state.read().await;
            assert!(
                !snapshot_diagnostics(&state, &parent_uri).is_empty(),
                "the stale unified-index entry must shadow lower tiers (test precondition)"
            );
        }

        // Open + close helper.R (buffer identical to disk): the close resync
        // must drop the stale unified-index entry so the fresh disk commit
        // becomes visible to the dependent.
        open_doc_with_revalidation_handoff(
            backend,
            &helper_uri,
            "r",
            1,
            "helper_fn <- function() 1\n",
        )
        .await;
        let (_, resync, resync_handoff) =
            close_with_final_handoff_capture(backend, &helper_uri, true).await;
        let (fresh_contents, diagnostics) = {
            let state = backend.state.read().await;
            (
                state
                    .workspace_index
                    .get(&helper_uri)
                    .map(|entry| entry.contents.to_string()),
                snapshot_diagnostics(&state, &parent_uri),
            )
        };
        let resync_handoff =
            resync_handoff.expect("the target close resync handoff must remain paused");
        release_and_wait_final_handoff(backend, &resync_handoff, "close-resync", &[&parent_uri])
            .await;
        assert!(
            resync.iter().any(|consumer| consumer.uri() == &parent_uri),
            "the target close resync must own the dependent revalidation"
        );
        assert_eq!(
            fresh_contents.as_deref(),
            Some("helper_fn <- function() 1\n"),
            "close resync must replace the stale unified-index entry with current disk state"
        );
        assert!(
            diagnostics.is_empty(),
            "close resync must invalidate the stale unified-index entry that shadows disk state"
        );
    }

    /// Rmd/Quarto close resync goes through the masking pipeline: disk
    /// metadata comes from chunk bodies only, so an unsaved chunk edit
    /// reverts and prose `source()` mentions never become edges.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn close_resync_rmd_uses_masked_disk_content() {
        let tmp = TempDir::new().unwrap();
        fs::write(tmp.path().join("helpers.R"), "helper_fn <- function() 1\n").unwrap();
        fs::write(tmp.path().join("extra.R"), "extra_fn <- function() 2\n").unwrap();
        // The prose decoy target exists on disk, so an unmasked parse WOULD
        // resolve it into an edge — masking is what keeps it out.
        fs::write(tmp.path().join("prose_decoy.R"), "d <- 1\n").unwrap();
        let rmd_disk = concat!(
            "# Report\n",
            "\n",
            "Prose calls source(\"prose_decoy.R\") but that is not R.\n",
            "\n",
            "```{r}\n",
            "source(\"helpers.R\")\n",
            "```\n",
        );
        fs::write(tmp.path().join("analysis.Rmd"), rmd_disk).unwrap();
        let (svc, rmd_uri) =
            open_in_quiescent_workspace(&tmp, "analysis.Rmd", "rmd", rmd_disk).await;
        let backend = svc.inner();
        let helpers_uri = Url::from_file_path(tmp.path().join("helpers.R")).unwrap();
        let extra_uri = Url::from_file_path(tmp.path().join("extra.R")).unwrap();
        let decoy_uri = Url::from_file_path(tmp.path().join("prose_decoy.R")).unwrap();

        // Unsaved chunk edit swaps the source() target to extra.R.
        let rmd_buffer = concat!(
            "# Report\n",
            "\n",
            "Prose calls source(\"prose_decoy.R\") but that is not R.\n",
            "\n",
            "```{r}\n",
            "source(\"extra.R\")\n",
            "```\n",
        );
        change_doc(backend, &rmd_uri, 2, rmd_buffer).await;
        {
            let state = backend.state.read().await;
            assert!(
                state
                    .cross_file_graph
                    .get_dependencies(&rmd_uri)
                    .iter()
                    .any(|e| e.to == extra_uri),
                "unsaved chunk edit must point the edge at extra.R"
            );
        }

        close_doc(backend, &rmd_uri).await;

        let reverted = wait_for_state(backend, 5_000, |state| {
            let deps = state.cross_file_graph.get_dependencies(&rmd_uri);
            deps.iter().any(|e| e.to == helpers_uri) && !deps.iter().any(|e| e.to == extra_uri)
        })
        .await;
        assert!(
            reverted,
            "close must revert the Rmd's edge to the on-disk chunk target"
        );
        let state = backend.state.read().await;
        assert!(
            !state
                .cross_file_graph
                .get_dependencies(&rmd_uri)
                .iter()
                .any(|e| e.to == decoy_uri),
            "prose source() mentions must never become edges (masked extraction)"
        );
    }

    /// A chunkless Rmd on disk resyncs to empty analysis metadata: prose
    /// `source()` mentions never become edges, and a chunk edge that existed
    /// only in the discarded buffer disappears.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn close_resync_chunkless_rmd_yields_no_edges() {
        let tmp = TempDir::new().unwrap();
        fs::write(tmp.path().join("extra.R"), "extra_fn <- function() 2\n").unwrap();
        fs::write(tmp.path().join("prose_decoy.R"), "d <- 1\n").unwrap();
        // Disk version has NO chunks — only prose that mentions source().
        let rmd_disk = concat!(
            "# Report\n",
            "\n",
            "Prose calls source(\"prose_decoy.R\") but that is not R.\n",
        );
        fs::write(tmp.path().join("analysis.Rmd"), rmd_disk).unwrap();
        let (svc, rmd_uri) =
            open_in_quiescent_workspace(&tmp, "analysis.Rmd", "rmd", rmd_disk).await;
        let backend = svc.inner();

        // Unsaved buffer edit adds a chunk with a real source() edge.
        let rmd_buffer = concat!(
            "# Report\n",
            "\n",
            "Prose calls source(\"prose_decoy.R\") but that is not R.\n",
            "\n",
            "```{r}\n",
            "source(\"extra.R\")\n",
            "```\n",
        );
        change_doc(backend, &rmd_uri, 2, rmd_buffer).await;
        {
            let state = backend.state.read().await;
            assert!(
                !state.cross_file_graph.get_dependencies(&rmd_uri).is_empty(),
                "unsaved chunk edit must add an edge"
            );
        }

        close_doc(backend, &rmd_uri).await;

        let emptied = wait_for_state(backend, 5_000, |state| {
            state.cross_file_graph.get_dependencies(&rmd_uri).is_empty()
        })
        .await;
        assert!(
            emptied,
            "chunkless disk content must resync to zero edges (prose never counts)"
        );
    }

    /// A DELETED-only watcher batch with multiple files removes every file's
    /// cross-file state in one pass and settles the open dependent's
    /// force-republish marker before the handler returns (pins/package state
    /// recompute once per batch, after the loop).
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn watched_files_deleted_batch_removes_all_files() {
        use tower_lsp::lsp_types::{DidChangeWatchedFilesParams, FileChangeType, FileEvent};

        let tmp = TempDir::new().unwrap();
        fs::write(tmp.path().join("a.R"), "a_fn <- function() 1\n").unwrap();
        fs::write(tmp.path().join("b.R"), "b_fn <- function() 2\n").unwrap();
        let main = "source(\"a.R\")\nsource(\"b.R\")\na_fn()\nb_fn()\n";
        fs::write(tmp.path().join("main.R"), main).unwrap();
        let (svc, main_uri) = open_in_quiescent_workspace(&tmp, "main.R", "r", main).await;
        let backend = svc.inner();
        let a_uri = Url::from_file_path(tmp.path().join("a.R")).unwrap();
        let b_uri = Url::from_file_path(tmp.path().join("b.R")).unwrap();
        {
            let state = backend.state.read().await;
            assert_eq!(
                state.cross_file_graph.get_dependencies(&main_uri).len(),
                2,
                "both edges must exist before the deletions"
            );
        }

        fs::remove_file(tmp.path().join("a.R")).unwrap();
        fs::remove_file(tmp.path().join("b.R")).unwrap();
        backend
            .did_change_watched_files(DidChangeWatchedFilesParams {
                changes: vec![
                    FileEvent {
                        uri: a_uri.clone(),
                        typ: FileChangeType::DELETED,
                    },
                    FileEvent {
                        uri: b_uri.clone(),
                        typ: FileChangeType::DELETED,
                    },
                ],
            })
            .await;

        let state = backend.state.read().await;
        assert!(
            state
                .cross_file_graph
                .get_dependencies(&main_uri)
                .is_empty(),
            "both deleted files' edges must be removed in the one batch"
        );
        for uri in [&a_uri, &b_uri] {
            assert!(
                state.workspace_index.get_metadata(uri).is_none(),
                "index entry for {uri} must be invalidated"
            );
        }
        assert_eq!(
            state
                .diagnostics_gate
                .force_republish_count_for_test(&main_uri),
            0,
            "the dependent's force-republish marker must be consumed synchronously"
        );
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn watched_file_change_removes_stale_entry_when_now_project_excluded() {
        use tower_lsp::lsp_types::{DidChangeWatchedFilesParams, FileChangeType, FileEvent};

        let tmp = TempDir::new().unwrap();
        fs::write(
            tmp.path().join("raven.toml"),
            "[workspace]\nexclude = [\"ignored/**\"]\n[crossFile]\nindexWorkspace = false\n",
        )
        .unwrap();
        fs::create_dir(tmp.path().join("ignored")).unwrap();
        let ignored_path = tmp.path().join("ignored/stale.R");
        fs::write(&ignored_path, "fresh <- 1\n").unwrap();
        let root = Url::from_file_path(tmp.path()).unwrap();
        let ignored_uri = Url::from_file_path(&ignored_path).unwrap();

        let (svc, _socket) = tower_lsp::LspService::new(Backend::new);
        let backend = svc.inner();
        backend
            .initialize(InitializeParams {
                workspace_folders: Some(vec![WorkspaceFolder {
                    uri: root.clone(),
                    name: "t".into(),
                }]),
                ..Default::default()
            })
            .await
            .unwrap();

        {
            let state = backend.state.read().await;
            assert!(
                state.workspace_exclusions.is_excluded_uri(&ignored_uri),
                "test precondition: raven.toml exclusion must be compiled"
            );
        }

        {
            let stale = "stale <- 1\n";
            let tree = crate::parser_pool::with_parser(|p| p.parse(stale, None));
            let metadata = std::sync::Arc::new(crate::cross_file::CrossFileMetadata::default());
            let artifacts =
                std::sync::Arc::new(crate::cross_file::scope::ScopeArtifacts::default());
            let fs_meta = std::fs::metadata(&ignored_path).unwrap();
            let snapshot =
                crate::cross_file::file_cache::FileSnapshot::with_content_hash(&fs_meta, stale);
            let entry = crate::workspace_index::IndexEntry {
                contents: ropey::Rope::from_str(stale),
                tree,
                loaded_packages: Vec::new(),
                data_packages: vec![],
                snapshot: snapshot.clone(),
                metadata: metadata.clone(),
                artifacts: artifacts.clone(),
                indexed_at_version: 0,
            };
            let state = backend.state.write().await;
            state.workspace_index.insert(ignored_uri.clone(), entry);
        }

        backend
            .did_change_watched_files(DidChangeWatchedFilesParams {
                changes: vec![FileEvent {
                    uri: ignored_uri.clone(),
                    typ: FileChangeType::CHANGED,
                }],
            })
            .await;

        let state = backend.state.read().await;
        assert!(
            state.workspace_index.get(&ignored_uri).is_none(),
            "excluded watched-file change must remove stale unified index entry"
        );
        assert!(
            state.workspace_index.get_metadata(&ignored_uri).is_none(),
            "excluded watched-file change must remove stale artifact projection"
        );
    }

    /// Regression guard for the reopen race the shared-resync extraction
    /// closed: a watched CHANGED event racing a `did_open` of the same file
    /// must never clobber the fresh buffer's topology with stale disk state.
    /// (Pre-extraction, the async pass's graph update had no open-at-commit
    /// check; the workspace index self-guarded but the graph did not.)
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn watched_file_reopen_during_async_read_does_not_clobber_graph() {
        use tower_lsp::lsp_types::{DidChangeWatchedFilesParams, FileChangeType, FileEvent};

        let tmp = TempDir::new().unwrap();
        // Disk gains a source() edge; the buffer opened mid-flight has none.
        fs::write(tmp.path().join("helper.R"), "source(\"extra.R\")\nx <- 1\n").unwrap();
        fs::write(tmp.path().join("extra.R"), "extra_fn <- function() 2\n").unwrap();
        fs::write(tmp.path().join("other.R"), "y <- 1\n").unwrap();
        // Startup scanning and package routing are outside this test's subject.
        let (svc, _other_uri) = open_in_quiescent_workspace(&tmp, "other.R", "r", "y <- 1\n").await;
        let backend = svc.inner();
        let helper_uri = Url::from_file_path(tmp.path().join("helper.R")).unwrap();
        let extra_uri = Url::from_file_path(tmp.path().join("extra.R")).unwrap();

        // Pause after the watched transaction prepares stale disk state but
        // before its commit, then open a buffer with no edge.
        let (pre_commit, final_handoff) = {
            let state = backend.state.read().await;
            (
                state
                    .watched_package_pre_commit_test_pause
                    .arm(Url::parse(WATCHED_PACKAGE_PRE_COMMIT_PAUSE_URI).unwrap()),
                state
                    .watched_final_handoff_test_capture
                    .arm_for(helper_uri.as_str()),
            )
        };
        backend
            .did_change_watched_files(DidChangeWatchedFilesParams {
                changes: vec![FileEvent {
                    uri: helper_uri.clone(),
                    typ: FileChangeType::CHANGED,
                }],
            })
            .await;
        tokio::time::timeout(std::time::Duration::from_secs(5), pre_commit.wait_arrived())
            .await
            .expect("watched transaction must reach the pre-commit boundary");
        open_doc(backend, &helper_uri, "r", 1, "x <- 1\n").await;
        pre_commit.release();

        let handoff = wait_final_handoff_payload(
            backend,
            &final_handoff,
            "watched-reopen-during-read",
            &[&helper_uri],
        )
        .await;
        assert_eq!(
            handoff.outcome,
            crate::state::WatchedFinalHandoffOutcome::RetiredBeforeFinalHandoff
        );
        assert!(handoff.reserved.is_empty());
        assert!(handoff.transferred.is_empty());
        release_and_wait_final_handoff(
            backend,
            &final_handoff,
            "watched-reopen-during-read",
            &[&helper_uri],
        )
        .await;
        let state = backend.state.read().await;
        assert!(
            !state
                .cross_file_graph
                .get_dependencies(&helper_uri)
                .iter()
                .any(|e| e.to == extra_uri),
            "a stale watched-file disk commit must never clobber an open buffer's topology"
        );
    }

    /// The `raven/projectConfigLoaded` payload schema is a contract with
    /// the VS Code extension. Lock it down: `path: string` ⇒
    /// `source: "raven.toml" | ".lintr"`; `path: None` ⇒ both fields
    /// JSON `null`. The `path` field uses `Path::display()`, which is
    /// platform-dependent — build the test paths from a tempdir so the
    /// assertion stays correct on both Unix and Windows.
    #[test]
    fn project_config_loaded_payload_shape() {
        let tmp = TempDir::new().unwrap();

        let raven_toml = tmp.path().join("raven.toml");
        let payload = super::build_project_config_loaded_payload(Some(&raven_toml));
        assert_eq!(
            payload["path"].as_str(),
            Some(raven_toml.display().to_string().as_str())
        );
        assert_eq!(payload["source"].as_str(), Some("raven.toml"));

        let lintr = tmp.path().join(".lintr");
        let payload = super::build_project_config_loaded_payload(Some(&lintr));
        assert_eq!(
            payload["path"].as_str(),
            Some(lintr.display().to_string().as_str())
        );
        assert_eq!(payload["source"].as_str(), Some(".lintr"));

        let payload = super::build_project_config_loaded_payload(None);
        assert!(payload["path"].is_null());
        assert!(payload["source"].is_null());
    }

    /// `DiagnosticsSnapshot::build` (the snapshot site in `handlers.rs` that
    /// every diagnostics pass takes) must apply per-document
    /// `[[linting.overrides]]` patches when computing the effective
    /// `LintConfig`. This exercises the handlers-site refactor: two files
    /// under the same project produce snapshots with different
    /// `lint_config.line_length` values depending on which override globs
    /// they match.
    #[tokio::test]
    async fn published_diagnostics_use_per_file_override() {
        use tower_lsp::lsp_types::{DidOpenTextDocumentParams, TextDocumentItem};

        let tmp = TempDir::new().unwrap();
        fs::write(
            tmp.path().join("raven.toml"),
            r#"
[linting]
enabled = true
lineLength = 30
lineLengthSeverity = "warning"

[[linting.overrides]]
files = ["tests/**/*.R"]
lineLength = 200
"#,
        )
        .unwrap();
        fs::create_dir_all(tmp.path().join("tests")).unwrap();
        fs::create_dir_all(tmp.path().join("R")).unwrap();
        let r_path = tmp.path().join("R/a.R");
        let test_path = tmp.path().join("tests/test-a.R");
        // 80-column line: triggers in R/ (line_length = 30), not in tests/ (200).
        let long_line =
            "x_long_identifier <- 'sample value with a longer literal string' ; cat('hi')\n";
        fs::write(&r_path, long_line).unwrap();
        fs::write(&test_path, long_line).unwrap();

        let (svc, _socket) = tower_lsp::LspService::new(Backend::new);
        let backend = svc.inner();
        backend
            .initialize(InitializeParams {
                workspace_folders: Some(vec![WorkspaceFolder {
                    uri: Url::from_file_path(tmp.path()).unwrap(),
                    name: "t".into(),
                }]),
                initialization_options: Some(serde_json::json!({
                    "packages": { "enabled": false }
                })),
                ..Default::default()
            })
            .await
            .unwrap();

        let r_uri = Url::from_file_path(&r_path).unwrap();
        let test_uri = Url::from_file_path(&test_path).unwrap();

        backend
            .did_open(DidOpenTextDocumentParams {
                text_document: TextDocumentItem {
                    uri: r_uri.clone(),
                    language_id: "r".into(),
                    version: 1,
                    text: long_line.into(),
                },
            })
            .await;
        backend
            .did_open(DidOpenTextDocumentParams {
                text_document: TextDocumentItem {
                    uri: test_uri.clone(),
                    language_id: "r".into(),
                    version: 1,
                    text: long_line.into(),
                },
            })
            .await;

        // Build the snapshots that handlers.rs would build for each URI and
        // assert their effective LintConfig. This is the same struct +
        // build path that `handlers.rs:DiagnosticsSnapshot::build` takes
        // during a diagnostics pass.
        let state = backend.state.read().await;
        let r_snap = crate::handlers::DiagnosticsSnapshot::build(&state, &r_uri)
            .expect("snapshot built for R/a.R");
        let test_snap = crate::handlers::DiagnosticsSnapshot::build(&state, &test_uri)
            .expect("snapshot built for tests/test-a.R");
        assert_eq!(r_snap.lint_config.line_length, 30);
        assert_eq!(test_snap.lint_config.line_length, 200);
    }

    /// Issue #343: an open Rmd document must flow through the publish-path
    /// dispatch (`publish_diagnostics_inner` Phase 1 build + Phase 2 match
    /// guard) and produce chunk diagnostics. The document is opened via the
    /// real `did_open` path, whose open-document authority entry now stores
    /// masked-derived metadata/tree (#343 Task 5), so the snapshot is
    /// masked-correct: diagnostics fall only on R chunk-body lines, never
    /// prose. This mirrors the exact match arm in `publish_diagnostics_inner`:
    /// build the snapshot, then run `diagnostics_from_snapshot` iff
    /// `file_type == R`.
    #[tokio::test]
    async fn rmd_document_flows_through_publish_path_and_flags_chunk_error() {
        use tower_lsp::lsp_types::{DidOpenTextDocumentParams, TextDocumentItem};

        let tmp = TempDir::new().unwrap();
        let rmd_path = tmp.path().join("report.Rmd");
        // Prose + a chunk with a syntax error (`x <- (`) on document line 5.
        let content = "# Title\n\nSome [prose](url) here.\n\n```{r}\nx <- (\n```\n";
        fs::write(&rmd_path, content).unwrap();

        let (svc, _socket) = tower_lsp::LspService::new(Backend::new);
        let backend = svc.inner();
        backend
            .initialize(InitializeParams {
                workspace_folders: Some(vec![WorkspaceFolder {
                    uri: Url::from_file_path(tmp.path()).unwrap(),
                    name: "t".into(),
                }]),
                initialization_options: Some(serde_json::json!({
                    "packages": { "enabled": false }
                })),
                ..Default::default()
            })
            .await
            .unwrap();

        let uri = Url::from_file_path(&rmd_path).unwrap();
        backend
            .did_open(DidOpenTextDocumentParams {
                text_document: TextDocumentItem {
                    uri: uri.clone(),
                    language_id: "rmd".into(),
                    version: 1,
                    text: content.into(),
                },
            })
            .await;

        let state = backend.state.read().await;
        // `snapshot_diagnostics` reproduces the publish-path match guard.
        let diagnostics = snapshot_diagnostics(&state, &uri);

        assert!(
            diagnostics
                .iter()
                .any(|d| d.severity == Some(DiagnosticSeverity::ERROR) && d.range.start.line == 5),
            "the chunk syntax error must surface on document line 5 through the publish path, got {:?}",
            diagnostics
                .iter()
                .map(|d| (d.range.start.line, d.message.clone()))
                .collect::<Vec<_>>()
        );
        // Prose lines (heading, markdown link) must not produce diagnostics.
        assert!(
            diagnostics.iter().all(|d| d.range.start.line == 5),
            "no diagnostics may land on prose lines, got {:?}",
            diagnostics
                .iter()
                .map(|d| (d.range.start.line, d.message.clone()))
                .collect::<Vec<_>>()
        );
    }

    #[tokio::test]
    async fn stan_lsp_open_change_clear_and_close_lifecycle() {
        use futures_util::StreamExt;
        use std::time::Duration;
        use tower::{Service, ServiceExt};
        use tower_lsp::jsonrpc::Request;
        use tower_lsp::lsp_types::{
            DidChangeTextDocumentParams, DidCloseTextDocumentParams, DidOpenTextDocumentParams,
            PublishDiagnosticsParams, TextDocumentContentChangeEvent, TextDocumentIdentifier,
            TextDocumentItem, VersionedTextDocumentIdentifier,
        };

        let tmp = TempDir::new().unwrap();
        let invalid = "data { int N }\nmodel {}\n";
        let path = tmp.path().join("model.stan");
        fs::write(&path, invalid).unwrap();
        let uri = Url::from_file_path(&path).unwrap();
        let (mut svc, mut socket) = tower_lsp::LspService::new(Backend::new);
        let initialize = Request::build("initialize")
            .id(1)
            .params(
                serde_json::to_value(InitializeParams {
                    workspace_folders: Some(vec![WorkspaceFolder {
                        uri: Url::from_directory_path(tmp.path()).unwrap(),
                        name: "t".into(),
                    }]),
                    initialization_options: Some(serde_json::json!({
                        "diagnosticUris": [uri.to_string()],
                        "crossFile": { "indexWorkspace": false },
                        "diagnostics": { "stan": "on" },
                        "packages": { "enabled": false }
                    })),
                    ..Default::default()
                })
                .unwrap(),
            )
            .finish();
        let response = svc.ready().await.unwrap().call(initialize).await.unwrap();
        assert!(response.is_some_and(|response| response.is_ok()));
        let backend = svc.inner();
        {
            let mut state = backend.state.write().await;
            state.workspace_scan_complete = true;
            state.cross_file_config.revalidation_debounce_ms = 60_000;
        }
        backend
            .did_open(DidOpenTextDocumentParams {
                text_document: TextDocumentItem {
                    uri: uri.clone(),
                    language_id: "stan".into(),
                    version: 1,
                    text: invalid.into(),
                },
            })
            .await;

        backend.publish_diagnostics(&uri).await;
        let v1 = tokio::time::timeout(Duration::from_secs(5), socket.next())
            .await
            .expect("Stan v1 diagnostics must publish")
            .expect("client socket remains open");
        let v1: PublishDiagnosticsParams =
            serde_json::from_value(v1.params().unwrap().clone()).unwrap();
        assert_eq!(v1.uri, uri);
        assert!(!v1.diagnostics.is_empty());
        assert!(
            v1.diagnostics
                .iter()
                .all(|finding| finding.range.start.line == 0)
        );

        backend
            .did_change(DidChangeTextDocumentParams {
                text_document: VersionedTextDocumentIdentifier {
                    uri: uri.clone(),
                    version: 2,
                },
                content_changes: vec![TextDocumentContentChangeEvent {
                    range: None,
                    range_length: None,
                    text: "data { int N; }\nmodel {}\n".to_string(),
                }],
            })
            .await;
        backend.publish_diagnostics(&uri).await;
        let v2 = tokio::time::timeout(Duration::from_secs(5), socket.next())
            .await
            .expect("Stan v2 clear must publish")
            .expect("client socket remains open");
        let v2: PublishDiagnosticsParams =
            serde_json::from_value(v2.params().unwrap().clone()).unwrap();
        assert!(v2.diagnostics.is_empty());

        let invalid_v3 = "model {\n  target += ;\n}\n";
        fs::write(&path, invalid_v3).unwrap();
        backend
            .did_change(DidChangeTextDocumentParams {
                text_document: VersionedTextDocumentIdentifier {
                    uri: uri.clone(),
                    version: 3,
                },
                content_changes: vec![TextDocumentContentChangeEvent {
                    range: None,
                    range_length: None,
                    text: invalid_v3.to_string(),
                }],
            })
            .await;
        backend.publish_diagnostics(&uri).await;
        let v3 = tokio::time::timeout(Duration::from_secs(5), socket.next())
            .await
            .expect("Stan v3 diagnostics must publish")
            .expect("client socket remains open");
        let v3: PublishDiagnosticsParams =
            serde_json::from_value(v3.params().unwrap().clone()).unwrap();
        assert!(!v3.diagnostics.is_empty());
        assert!(v3.diagnostics.iter().all(|finding| {
            finding.range.start.line == 1
                && finding.code
                    == Some(tower_lsp::lsp_types::NumberOrString::String(
                        "syntax-error".to_string(),
                    ))
        }));

        backend
            .did_close(DidCloseTextDocumentParams {
                text_document: TextDocumentIdentifier { uri: uri.clone() },
            })
            .await;
        let close = tokio::time::timeout(Duration::from_secs(5), socket.next())
            .await
            .expect("Stan close must publish an empty clear")
            .expect("client socket remains open");
        let close: PublishDiagnosticsParams =
            serde_json::from_value(close.params().unwrap().clone()).unwrap();
        assert_eq!(close.uri, uri);
        assert!(close.diagnostics.is_empty());

        let document = {
            let state = backend.state.read().await;
            assert!(state.get_document(&uri).is_none());
            assert!(state.diagnostics_gate.current_epoch(&uri).is_none());
            let entry = state
                .workspace_index
                .get(&uri)
                .expect("close must install the disk-backed Stan entry");
            assert_eq!(entry.tree.as_ref().unwrap().root_node().kind(), "program");
            assert!(entry.metadata.sources.is_empty());
            assert!(entry.artifacts.exported_interface.is_empty());
            assert!(entry.loaded_packages.is_empty());
            assert!(entry.data_packages.is_empty());
            crate::state::document_from_workspace_entry(
                &uri,
                &entry,
                state.chunk_kind_for_closed_file(&uri),
            )
        };
        let mut diagnostic_state = super::WorldState::new();
        diagnostic_state.workspace_scan_complete = true;
        diagnostic_state.cross_file_config.stan_diagnostics_enabled = true;
        diagnostic_state.documents.insert(uri.clone(), document);
        assert!(!snapshot_diagnostics(&diagnostic_state, &uri).is_empty());
    }

